import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { InboxClient } from '@/components/inbox/InboxClient'
import type { RichInboxItem, InboxItemType } from '@/components/inbox/InboxClient'
// InboxItemType is the extended union (includes guest-residency-ending, review-request, etc.)
import type { TeamMember } from '@/components/inbox/AssignUserPicker'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

export const metadata: Metadata = {
  title: 'Inbox — InkOS',
}

export default async function InboxPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { studioId, role, plan } = activeStudio
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()
  const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
  const sevenDaysFromNow = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString()

  // Fetch all data sources in parallel
  const [
    pendingBookingsRes,
    consentSubmissionsRes,
    waitlistRes,
    newClientsRes,
    assignmentsRes,
    membersRes,
    unreadConversationsRes,
    guestResidenciesRes,
  ] = await Promise.all([
    // 1. Pending bookings — include scheduled_at for urgency
    supabase
      .from('bookings')
      .select('id, created_at, scheduled_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'pending')
      .eq('deposit_paid', false)
      .order('scheduled_at', { ascending: true })
      .limit(50),

    // 2. Bookings with consent required but not yet signed (last 7d)
    supabase
      .from('bookings')
      .select('id, client_id, created_at, scheduled_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('consent_required', true)
      .is('consent_signed_at', null)
      .gte('created_at', sevenDaysAgo)
      .order('scheduled_at', { ascending: true })
      .limit(30),

    // 3. Waitlist entries (last 24h)
    supabase
      .from('waitlist_entries')
      .select('id, client_id, created_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'active')
      .gte('created_at', oneDayAgo)
      .order('created_at', { ascending: false })
      .limit(20),

    // 4. New clients (last 7d)
    supabase
      .from('clients')
      .select('id, first_name, last_name, created_at')
      .eq('studio_id', studioId)
      .gte('created_at', sevenDaysAgo)
      .is('archived_at', null)
      .order('created_at', { ascending: false })
      .limit(10),

    // 5. Inbox assignments — include state so the client can hide active,
    //    archived/resolved, and snoozed rows correctly.
    supabase
      .from('inbox_assignments')
      .select('item_kind, item_id, assigned_to, snoozed_until, archived_at, resolved_at')
      .eq('studio_id', studioId)
      .limit(500),

    // 6. Studio members for assignment picker
    supabase
      .from('studio_members')
      .select('user_id, role, profiles(full_name, avatar_url)')
      .eq('studio_id', studioId)
      .is('deactivated_at', null),

    // 7. Unread message conversations
    supabase
      .from('conversations')
      .select('id, client_id, display_name, last_message_preview, last_message_at, unread_count, channel')
      .eq('studio_id', studioId)
      .is('archived_at', null)
      .gt('unread_count', 0)
      .order('last_message_at', { ascending: false })
      .limit(50),

    // 8. Guest residencies ending within 7 days
    //    ends_at and residency_started_at were added by migration
    //    20260422110200_studio_members_residency_dates.sql. The generated types.ts
    //    has not been refreshed yet; we select via .select() and cast the result
    //    to a typed intermediate to avoid touching the generated file.
    //    TODO: remove the cast once pnpm db:types is run after this migration.
    supabase
      .from('studio_members')
      .select('id, user_id, role, ends_at, profiles(full_name)')
      .eq('studio_id', studioId)
      .eq('role', 'guest_artist')
      .not('ends_at', 'is', null)
      .gte('ends_at', new Date().toISOString())
      .lte('ends_at', sevenDaysFromNow)
      .is('deactivated_at', null)
      .order('ends_at', { ascending: true })
      .limit(20),
  ])

  // Build assignment map: key = `${kind}-${item_id}`
  type AssignmentState = {
    assignedTo: string | null
    snoozedUntil: string | null
    archivedAt: string | null
    resolvedAt: string | null
  }

  const assignmentMap = new Map<string, AssignmentState>()
  for (const a of assignmentsRes.data ?? []) {
    assignmentMap.set(`${a.item_kind}-${a.item_id}`, {
      assignedTo: a.assigned_to,
      snoozedUntil: a.snoozed_until,
      archivedAt: a.archived_at,
      resolvedAt: a.resolved_at,
    })
  }

  function getAssignment(kind: InboxItemType, itemId: string): AssignmentState {
    return assignmentMap.get(`${kind}-${itemId}`) ?? {
      assignedTo: null,
      snoozedUntil: null,
      archivedAt: null,
      resolvedAt: null,
    }
  }

  // Normalize into RichInboxItem[]
  const items: RichInboxItem[] = []

  // Pending bookings (deposit overdue)
  for (const booking of pendingBookingsRes.data ?? []) {
    const clientRow = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('deposit', booking.id)

    items.push({
      id: `booking-${booking.id}`,
      type: 'deposit' as InboxItemType,
      title: 'Deposit pending',
      subtitle: clientName,
      actionLabel: 'View booking',
      actionHref: `/bookings/${booking.id}`,
      timestamp: booking.created_at,
      scheduledAt: booking.scheduled_at,
      ...a,
    })
  }

  // Bookings with unsigned consent forms
  for (const booking of consentSubmissionsRes.data ?? []) {
    const clientRow = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('form', booking.id)

    items.push({
      id: `consent-${booking.id}`,
      type: 'form' as InboxItemType,
      title: 'Consent form unsigned',
      subtitle: clientName,
      actionLabel: 'View booking',
      actionHref: `/bookings/${booking.id}`,
      timestamp: booking.created_at,
      scheduledAt: booking.scheduled_at,
      ...a,
    })
  }

  // Waitlist entries
  for (const entry of waitlistRes.data ?? []) {
    const clientRow = Array.isArray(entry.clients) ? entry.clients[0] : entry.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('waitlist', entry.id)

    items.push({
      id: `waitlist-${entry.id}`,
      type: 'waitlist' as InboxItemType,
      title: 'New waitlist signup',
      subtitle: clientName,
      actionLabel: 'View',
      actionHref: `/clients/${entry.client_id}`,
      timestamp: entry.created_at,
      scheduledAt: null,
      ...a,
    })
  }

  // New clients
  for (const client of newClientsRes.data ?? []) {
    const clientName = `${client.first_name}${client.last_name ? ` ${client.last_name}` : ''}`
    const a = getAssignment('client', client.id)

    items.push({
      id: `client-${client.id}`,
      type: 'client' as InboxItemType,
      title: 'New client',
      subtitle: clientName,
      actionLabel: 'View',
      actionHref: `/clients/${client.id}`,
      timestamp: client.created_at,
      scheduledAt: null,
      ...a,
    })
  }

  // Unread message conversations
  for (const conv of unreadConversationsRes.data ?? []) {
    const preview = conv.last_message_preview
      ? String(conv.last_message_preview).slice(0, 80)
      : 'New message'
    const clientId = conv.client_id as string | null
    const a = clientId ? getAssignment('client', clientId) : {
      assignedTo: null,
      snoozedUntil: null,
      archivedAt: null,
      resolvedAt: null,
    }

    items.push({
      id: `conv-${conv.id as string}`,
      type: 'unread-message' as InboxItemType,
      title: String(conv.display_name ?? 'Message'),
      subtitle: preview,
      actionLabel: 'Reply',
      actionHref: clientId ? `/clients/${clientId}?tab=comms` : '/inbox',
      timestamp: conv.last_message_at as string ?? new Date().toISOString(),
      scheduledAt: null,
      ...a,
    })
  }

  // Guest residencies ending within 7 days
  // Cast via typed intermediate because ends_at is not yet in generated types.
  // TODO: remove cast once pnpm db:types is run post-migration 20260422110200.
  interface GuestResidencyRow {
    id: string
    user_id: string
    role: string
    ends_at: string
    profiles: { full_name: string | null } | { full_name: string | null }[] | null
  }

  for (const rawRow of (guestResidenciesRes.data ?? []) as unknown as GuestResidencyRow[]) {
    const profileRow = Array.isArray(rawRow.profiles) ? rawRow.profiles[0] : rawRow.profiles
    const artistName = profileRow?.full_name ?? 'Guest artist'

    const endsAt = new Date(rawRow.ends_at)
    const msUntil = endsAt.getTime() - Date.now()
    const daysUntil = Math.ceil(msUntil / (24 * 60 * 60 * 1000))
    const formattedEndsAt = endsAt.toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
    })

    // TODO(open-slots): compute open booking slots during the residency window
    // and surface the count here. For v1, surface all ending residencies.

    const a = getAssignment('guest-residency-ending' as InboxItemType, rawRow.id)

    // actionHref → calendar filtered to this artist from today to ends_at
    const calendarHref = `/calendar?artist_id=${rawRow.user_id}&from=today&to=${rawRow.ends_at.slice(0, 10)}`

    items.push({
      id: `residency-${rawRow.id}`,
      type: 'guest-residency-ending' as InboxItemType,
      title: `${artistName} · Guest residency ending in ${daysUntil} day${daysUntil === 1 ? '' : 's'}`,
      subtitle: `Ends ${formattedEndsAt} · Market remaining slots`,
      actionLabel: 'Market slots',
      actionHref: calendarHref,
      timestamp: rawRow.ends_at,
      scheduledAt: rawRow.ends_at,
      ...a,
    })
  }

  // Sort by timestamp descending
  items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())

  // Build team members list for assignment picker
  const members: TeamMember[] = (membersRes.data ?? []).map((m) => {
    const profileRow = Array.isArray(m.profiles) ? m.profiles[0] : m.profiles
    return {
      userId: m.user_id,
      name: profileRow?.full_name ?? m.user_id,
      role: m.role,
      avatarUrl: profileRow?.avatar_url ?? null,
    }
  })

  return (
    <InboxClient
      items={items}
      members={members}
      currentUserId={user.id}
      currentPlan={plan as PlanTier}
      currentRole={role as NavRole}
    />
  )
}

/**
 * Urgency computation for inbox items.
 *
 * Rules:
 *   now       — deposit pending for booking < 24h away; form unsigned for booking < 24h away
 *   today     — pending bookings in next 48h; waitlist signups < 24h old
 *   this_week — new clients < 7d ago (not yet booked); consent forms unsigned > 24h
 *   later     — everything else
 */

// InboxItemType is imported from InboxClient which extends InboxItemKind with
// kinds pending Dato migration. urgency.ts uses it to avoid a separate re-export.
import type { InboxItemType } from '@/components/inbox/InboxClient'

export type Urgency = 'now' | 'today' | 'this_week' | 'later'

export interface UrgencyMeta {
  label: string
  /** Tailwind text colour class */
  textClass: string
  /** Tailwind bg colour class for the dot */
  dotClass: string
  /** Tailwind border colour class for the group header */
  borderClass: string
}

export const URGENCY_META: Record<Urgency, UrgencyMeta> = {
  now: {
    label: 'Now',
    textClass: 'text-red-500 dark:text-red-400',
    dotClass: 'bg-red-500',
    borderClass: 'border-red-500/20',
  },
  today: {
    label: 'Today',
    textClass: 'text-amber-500 dark:text-amber-400',
    dotClass: 'bg-amber-500',
    borderClass: 'border-amber-500/20',
  },
  this_week: {
    label: 'This Week',
    textClass: 'text-rust',
    dotClass: 'bg-rust',
    borderClass: 'border-rust/20',
  },
  later: {
    label: 'Later',
    textClass: 'text-muted-foreground',
    dotClass: 'bg-muted-foreground/40',
    borderClass: 'border-border/30',
  },
}

export const URGENCY_ORDER: Urgency[] = ['now', 'today', 'this_week', 'later']

export interface InboxItemForUrgency {
  type: InboxItemType
  /** ISO timestamp of the item itself (created_at or updated_at) */
  timestamp: string
  /** For deposit / form items: the booking's scheduled_at — ISO string */
  scheduledAt?: string | null
}

/**
 * Compute urgency for a single inbox item.
 * All comparisons are client-side from `Date.now()`.
 */
export function computeUrgency(item: InboxItemForUrgency): Urgency {
  const now = Date.now()
  const h24 = 24 * 60 * 60 * 1000
  const h48 = 48 * 60 * 60 * 1000
  const d7 = 7 * 24 * 60 * 60 * 1000

  const itemAge = now - new Date(item.timestamp).getTime()

  if (item.type === 'deposit') {
    if (item.scheduledAt) {
      const msUntil = new Date(item.scheduledAt).getTime() - now
      if (msUntil >= 0 && msUntil < h24) return 'now'
      if (msUntil >= 0 && msUntil < h48) return 'today'
    }
    return 'later'
  }

  if (item.type === 'form') {
    if (item.scheduledAt) {
      const msUntil = new Date(item.scheduledAt).getTime() - now
      if (msUntil >= 0 && msUntil < h24) return 'now'
    }
    // Form unsigned for >24h → this_week
    if (itemAge > h24) return 'this_week'
    return 'today'
  }

  if (item.type === 'waitlist') {
    // Signups < 24h → today
    if (itemAge < h24) return 'today'
    return 'later'
  }

  if (item.type === 'client') {
    // New clients < 7d → this_week
    if (itemAge < d7) return 'this_week'
    return 'later'
  }

  if (item.type === 'guest-residency-ending') {
    // scheduledAt holds ends_at for this kind
    if (item.scheduledAt) {
      const msUntil = new Date(item.scheduledAt).getTime() - now
      if (msUntil >= 0 && msUntil <= h48) return 'today'
      if (msUntil > h48) return 'this_week'
    }
    return 'later'
  }

  return 'later'
}

'use client'

import { useState, useCallback, useMemo } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import type { LucideIcon } from 'lucide-react'
import {
  Archive,
  CheckCircle2,
  Clock3,
  Inbox,
  Keyboard,
  ListChecks,
  Search,
  SearchX,
  TimerReset,
  UserRoundCheck,
  X,
} from 'lucide-react'
import { EmptyState } from '@/components/shared/EmptyState'
import { PageHeader } from '@/components/shared/PageHeader'
import { PageTabs } from '@/components/shared/PageTabs'
import { PageViews } from '@/components/shared/PageViews'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { cn } from '@/lib/utils'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { PageTab } from '@/components/shared/PageTabs'
import type { InboxItemKind } from '@/lib/supabase/types'
import { computeUrgency, URGENCY_ORDER } from '@/lib/inbox/urgency'
import type { Urgency } from '@/lib/inbox/urgency'
import { UrgencyGroup } from './UrgencyGroup'
import { InboxItemRow } from './InboxItemRow'
import { BatchActionBar } from './BatchActionBar'
import type { TeamMember } from './AssignUserPicker'
import { useInboxShortcuts, INBOX_SHORTCUTS } from '@/hooks/use-inbox-shortcuts'
import { PageShell } from '@/components/shared/PageShell'

// ─── Types ────────────────────────────────────────────────────

// Extend the generated InboxItemKind with kinds pending Dato migration + db:types regen.
// Remove each entry here once pnpm db:types picks up the enum value.
export type InboxItemType =
  | InboxItemKind
  | 'review-request'
  | 'client-birthday'
  | 'guest-residency-ending'

export interface InboxItem {
  id: string
  type: InboxItemType
  title: string
  subtitle: string
  actionLabel: string
  actionHref: string
  timestamp: string
}

/** Extended item with urgency-related fields and assignment state */
export interface RichInboxItem extends InboxItem {
  scheduledAt: string | null
  assignedTo: string | null
  resolvedAt: string | null
  archivedAt: string | null
  snoozedUntil: string | null
}

interface InboxClientProps {
  items: RichInboxItem[]
  members: TeamMember[]
  currentUserId: string
  currentPlan: PlanTier
  currentRole: NavRole
}

type TabKey = 'all' | 'deposits' | 'forms' | 'clients' | 'messages'

const VALID_TABS: TabKey[] = ['all', 'deposits', 'forms', 'clients', 'messages']

const TABS: PageTab[] = [
  { key: 'all', label: 'All', href: '/inbox' },
  { key: 'deposits', label: 'Deposits', href: '/inbox?tab=deposits' },
  { key: 'forms', label: 'Forms', href: '/inbox?tab=forms' },
  { key: 'clients', label: 'Clients', href: '/inbox?tab=clients' },
  { key: 'messages', label: 'Messages', href: '/inbox?tab=messages' },
]

interface SelectedItem {
  id: string
  type: InboxItemType
}

interface InboxMetricCardProps {
  icon: LucideIcon
  label: string
  value: string | number
  detail: string
  tone?: 'default' | 'dark' | 'rust' | 'success'
}

function isFutureSnoozed(item: RichInboxItem): boolean {
  if (!item.snoozedUntil) return false
  const snoozedUntil = new Date(item.snoozedUntil).getTime()
  return Number.isFinite(snoozedUntil) && snoozedUntil > Date.now()
}

function isOpenItem(item: RichInboxItem): boolean {
  return item.archivedAt === null && item.resolvedAt === null && !isFutureSnoozed(item)
}

function itemBelongsToTab(item: RichInboxItem, tab: TabKey): boolean {
  if (tab === 'all') return true
  if (tab === 'deposits') return item.type === 'deposit'
  if (tab === 'forms') return item.type === 'form'
  if (tab === 'clients') return item.type === 'client' || item.type === 'waitlist'
  if (tab === 'messages') return item.type === 'unread-message'
  return true
}

function countForTab(items: RichInboxItem[], tab: string): number {
  return items.filter((item) => itemBelongsToTab(item, tab as TabKey)).length
}

function matchesSearch(item: RichInboxItem, query: string): boolean {
  if (!query) return true
  return [
    item.title,
    item.subtitle,
    item.actionLabel,
    item.type.replace(/-/g, ' '),
  ]
    .join(' ')
    .toLowerCase()
    .includes(query)
}

function urgencyFor(item: RichInboxItem): Urgency {
  return computeUrgency({
    type: item.type,
    timestamp: item.timestamp,
    scheduledAt: item.scheduledAt,
  })
}

function InboxMetricCard({
  icon: Icon,
  label,
  value,
  detail,
  tone = 'default',
}: InboxMetricCardProps) {
  return (
    <div
      className={cn(
        'rounded-lg border p-4 shadow-[var(--shadow-soft)]',
        'flex min-h-[116px] flex-col justify-between gap-4',
        tone === 'dark'
          ? 'border-[var(--color-onyx)] bg-[var(--color-onyx)] text-[var(--color-bone)]'
          : 'border-border/70 bg-card',
      )}
    >
      <div className="flex items-start justify-between gap-3">
        <p
          className={cn(
            'text-[10px] font-bold uppercase tracking-[0.12em]',
            tone === 'dark' ? 'text-[rgba(247,247,245,0.58)]' : 'text-muted-foreground',
          )}
        >
          {label}
        </p>
        <span
          className={cn(
            'flex h-8 w-8 shrink-0 items-center justify-center rounded-lg',
            tone === 'dark' && 'bg-[rgba(247,247,245,0.1)] text-[var(--color-bone)]',
            tone === 'rust' && 'bg-[var(--color-chip-rust-bg)] text-[var(--color-rust)]',
            tone === 'success' && 'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)]',
            tone === 'default' && 'bg-muted text-foreground/70',
          )}
          aria-hidden="true"
        >
          <Icon className="h-4 w-4" />
        </span>
      </div>
      <div>
        <p
          className={cn(
            'font-serif text-[28px] italic leading-none tabular-nums',
            tone === 'dark' ? 'text-[var(--color-bone)]' : 'text-foreground',
          )}
        >
          {value}
        </p>
        <p
          className={cn(
            'mt-1.5 text-[12px] leading-snug',
            tone === 'dark' ? 'text-[rgba(247,247,245,0.62)]' : 'text-muted-foreground',
          )}
        >
          {detail}
        </p>
      </div>
    </div>
  )
}

// ─── Component ────────────────────────────────────────────────

export function InboxClient({
  items,
  members,
  currentUserId,
  currentPlan,
  currentRole,
}: InboxClientProps) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const rawTab = searchParams.get('tab')
  const activeTab: TabKey = VALID_TABS.includes(rawTab as TabKey) ? (rawTab as TabKey) : 'all'

  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [focusedId, setFocusedId] = useState<string | null>(null)
  const [showCheatsheet, setShowCheatsheet] = useState(false)
  const [showArchived, setShowArchived] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')

  const normalizedQuery = searchQuery.trim().toLowerCase()

  const openItems = useMemo(() => items.filter(isOpenItem), [items])
  const nowCount = useMemo(
    () => openItems.filter((item) => urgencyFor(item) === 'now').length,
    [openItems],
  )
  const todayCount = useMemo(
    () => openItems.filter((item) => urgencyFor(item) === 'today').length,
    [openItems],
  )
  const assignedToMeCount = useMemo(
    () => openItems.filter((item) => item.assignedTo === currentUserId).length,
    [currentUserId, openItems],
  )
  const unassignedCount = useMemo(
    () => openItems.filter((item) => item.assignedTo === null).length,
    [openItems],
  )
  const heldCount = useMemo(
    () => items.filter((item) => item.archivedAt !== null || item.resolvedAt !== null || isFutureSnoozed(item)).length,
    [items],
  )

  const tabCountSource = showArchived ? items : openItems
  const tabs: PageTab[] = useMemo(
    () => TABS.map((tab) => {
      const count = countForTab(tabCountSource, tab.key)
      return count > 0 ? { ...tab, badge: count } : tab
    }),
    [tabCountSource],
  )

  const tabFiltered: RichInboxItem[] = useMemo(
    () => items.filter((item) => itemBelongsToTab(item, activeTab)),
    [activeTab, items],
  )

  const stateFiltered: RichInboxItem[] = useMemo(
    () => showArchived ? tabFiltered : tabFiltered.filter(isOpenItem),
    [showArchived, tabFiltered],
  )

  const visibleItems: RichInboxItem[] = useMemo(
    () => stateFiltered.filter((item) => matchesSearch(item, normalizedQuery)),
    [normalizedQuery, stateFiltered],
  )

  const groups: Record<Urgency, RichInboxItem[]> = useMemo(() => {
    const nextGroups: Record<Urgency, RichInboxItem[]> = {
      now: [],
      today: [],
      this_week: [],
      later: [],
    }

    for (const item of visibleItems) {
      nextGroups[urgencyFor(item)].push(item)
    }

    return nextGroups
  }, [visibleItems])

  const orderedItems: RichInboxItem[] = useMemo(
    () => URGENCY_ORDER.flatMap((u) => groups[u]),
    [groups],
  )

  // ── Selection helpers ──
  const toggleSelect = useCallback((id: string) => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  const clearSelection = useCallback(() => setSelected(new Set()), [])

  // ── Focus helpers ──
  const focusItem = useCallback((id: string) => {
    setFocusedId(id)
    const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${id}"]`)
    el?.focus()
    el?.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
  }, [])

  // ── Refresh ──
  const refresh = useCallback(() => {
    router.refresh()
  }, [router])

  // ── Keyboard shortcuts ──
  useInboxShortcuts({
    onNavigateDown: () => {
      if (orderedItems.length === 0) return
      const idx = orderedItems.findIndex((i) => i.id === focusedId)
      const next = idx === -1 ? 0 : Math.min(idx + 1, orderedItems.length - 1)
      const nextItem = orderedItems[next]
      if (nextItem) focusItem(nextItem.id)
    },
    onNavigateUp: () => {
      if (orderedItems.length === 0) return
      const idx = orderedItems.findIndex((i) => i.id === focusedId)
      const prev = idx <= 0 ? 0 : idx - 1
      const prevItem = orderedItems[prev]
      if (prevItem) focusItem(prevItem.id)
    },
    onArchiveFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      el?.querySelector<HTMLElement>('[aria-label="More options"]')?.click()
    },
    onAssignFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      el?.querySelector<HTMLElement>('[aria-label="Assign to team member"]')?.click()
    },
    onResolveFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      el?.querySelector<HTMLElement>('[aria-label="More options"]')?.click()
    },
    onToggleFocusedCheckbox: () => {
      if (focusedId) toggleSelect(focusedId)
    },
    onShowCheatsheet: () => setShowCheatsheet(true),
  })

  const selectedItems: SelectedItem[] = orderedItems
    .filter((i) => selected.has(i.id))
    .map((i) => ({ id: i.id, type: i.type }))

  const hasNonEmpty = URGENCY_ORDER.some((u) => groups[u].length > 0)
  const hasSearch = normalizedQuery.length > 0

  return (
    <>
      <PageShell>
        <PageHeader
          title="Inbox"
          description="Action items that need your attention"
          actions={
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowCheatsheet(true)}
              aria-label="Show keyboard shortcuts"
              className="h-8 w-8 p-0 text-muted-foreground/70 hover:text-foreground"
            >
              <Keyboard className="h-4 w-4" aria-hidden="true" />
            </Button>
          }
        />

        <section
          aria-label="Inbox overview"
          className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4"
        >
          <InboxMetricCard
            icon={ListChecks}
            label="Open queue"
            value={openItems.length}
            detail={`${countForTab(openItems, activeTab)} in this view`}
            tone="dark"
          />
          <InboxMetricCard
            icon={Clock3}
            label="Priority"
            value={nowCount + todayCount}
            detail={nowCount > 0 ? `${nowCount} now · ${todayCount} today` : `${todayCount} due today`}
            tone="rust"
          />
          <InboxMetricCard
            icon={UserRoundCheck}
            label="Assigned to you"
            value={assignedToMeCount}
            detail={`${unassignedCount} unassigned`}
            tone="success"
          />
          <InboxMetricCard
            icon={TimerReset}
            label="Held"
            value={heldCount}
            detail="Archived, resolved, or snoozed"
          />
        </section>

        <PageViews
          actions={
            <Button
              variant={showArchived ? 'default' : 'outline'}
              size="sm"
              onClick={() => setShowArchived((v) => !v)}
              aria-label={showArchived ? 'Showing all inbox states' : 'Showing active inbox queue'}
              className="h-8 gap-1.5 text-xs"
            >
              <Archive className="h-3.5 w-3.5" aria-hidden="true" />
              <span className="hidden sm:inline">
                {showArchived ? 'All states' : 'Active queue'}
              </span>
            </Button>
          }
        >
          <PageTabs
            tabs={tabs}
            activeKey={activeTab}
            currentPlan={currentPlan}
            currentRole={currentRole}
          />
        </PageViews>

        <div className="rounded-lg border border-border/70 bg-card/90 p-3 shadow-[var(--shadow-soft)]">
          <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div className="relative min-w-0 flex-1">
              <Search
                className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground"
                aria-hidden="true"
              />
              <Input
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                aria-label="Search action items"
                placeholder="Search action items"
                className="h-9 bg-muted/30 pl-9 pr-9 text-sm"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => setSearchQuery('')}
                  aria-label="Clear search"
                  className="absolute right-2.5 top-1/2 flex h-5 w-5 -translate-y-1/2 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                >
                  <X className="h-3.5 w-3.5" aria-hidden="true" />
                </button>
              )}
            </div>

            <div className="flex flex-wrap items-center gap-2 text-[12px] text-muted-foreground">
              <span className="rounded-md border border-border/70 bg-background px-2 py-1 tabular-nums">
                {visibleItems.length} shown
              </span>
              <span className="rounded-md border border-border/70 bg-background px-2 py-1">
                {showArchived ? 'All states' : 'Active only'}
              </span>
              {hasSearch && (
                <span className="rounded-md border border-border/70 bg-background px-2 py-1">
                  Search filtered
                </span>
              )}
            </div>
          </div>
        </div>

        {selected.size > 0 && (
          <div aria-live="polite">
            <BatchActionBar
              selected={selectedItems}
              members={members}
              currentUserId={currentUserId}
              onClear={clearSelection}
              onRefresh={refresh}
            />
          </div>
        )}

        <div className="flex-1 space-y-4">
          {!hasNonEmpty ? (
            <EmptyState
              icon={hasSearch ? SearchX : Inbox}
              title={hasSearch ? 'No matching action items' : 'Inbox is clear'}
              description={
                hasSearch
                  ? 'Try another name, item type, or client.'
                  : activeTab === 'all'
                    ? "You're all caught up. New action items appear here automatically."
                    : 'No items in this category right now.'
              }
              className="max-w-none rounded-lg border border-border/70 bg-card/80 shadow-[var(--shadow-soft)]"
              data-testid="inbox-empty-full"
            />
          ) : (
            URGENCY_ORDER.map((urgency) => {
              const groupItems = groups[urgency]
              if (groupItems.length === 0) {
                if (urgency === 'now') {
                  return (
                    <div
                      key="now-empty"
                      data-testid="inbox-empty-now"
                      className="flex items-center gap-2 rounded-lg border border-[var(--color-success)]/20 bg-[var(--color-success-bg)]/70 px-4 py-3 text-[13px] text-[var(--color-success-foreground)]"
                    >
                      <CheckCircle2 className="h-4 w-4 shrink-0" aria-hidden="true" />
                      <span>Nothing overdue. Well done.</span>
                    </div>
                  )
                }
                return null
              }
              const defaultExpanded = urgency === 'now' || urgency === 'today' || urgency === 'this_week'

              return (
                <UrgencyGroup
                  key={urgency}
                  urgency={urgency}
                  count={groupItems.length}
                  defaultExpanded={defaultExpanded}
                >
                  {groupItems.map((item) => (
                    <InboxItemRow
                      key={item.id}
                      item={item}
                      urgency={urgency}
                      isSelected={selected.has(item.id)}
                      isFocused={focusedId === item.id}
                      members={members}
                      currentUserId={currentUserId}
                      onToggleSelect={toggleSelect}
                      onFocus={setFocusedId}
                      onRefresh={refresh}
                    />
                  ))}
                </UrgencyGroup>
              )
            })
          )}
        </div>
      </PageShell>

      <Dialog open={showCheatsheet} onOpenChange={setShowCheatsheet}>
        <DialogContent className="max-w-xs">
          <DialogHeader>
            <DialogTitle className="text-sm font-semibold">Keyboard shortcuts</DialogTitle>
          </DialogHeader>
          <div className="mt-2 space-y-1.5">
            {INBOX_SHORTCUTS.map(({ key, description }) => (
              <div key={key} className="flex items-center justify-between gap-4">
                <span className="text-xs text-muted-foreground">{description}</span>
                <kbd className="inline-flex h-5 min-w-[1.25rem] items-center justify-center rounded border border-border/60 bg-muted px-1 font-mono text-[10px] text-foreground">
                  {key}
                </kbd>
              </div>
            ))}
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}

