interface InboxItemRowProps {
  item: RichInboxItem
  urgency: Urgency
  isSelected: boolean
  isFocused: boolean
  members: TeamMember[]
  currentUserId: string
  onToggleSelect: (id: string) => void
  onFocus: (id: string) => void
  onRefresh: () => void
}

// Safely cast item.type to ExtendedInboxItemKind. InboxItemType already includes
// extended kinds, so this is a structural pass-through to satisfy the switch exhaustion.
function asExtended(kind: InboxItemType): ExtendedInboxItemKind {
  return kind as ExtendedInboxItemKind
}

// Extended kind type — includes kinds that are pending Dato migration + db:types
// regeneration. Remove each entry once pnpm db:types picks up the enum value.
type ExtendedInboxItemKind =
  | InboxItemKind
  | 'review-request'
  | 'client-birthday'
  | 'guest-residency-ending'

function canUpdateAssignment(type: ExtendedInboxItemKind): boolean {
  return type === 'deposit' || type === 'form' || type === 'client' || type === 'waitlist'
}

function typeIcon(type: ExtendedInboxItemKind) {
  switch (type) {
    case 'deposit': return <CheckCircle2 className="h-4 w-4 text-[var(--color-warning-foreground)]" aria-hidden="true" />
    case 'form': return <FileText className="h-4 w-4 text-[var(--color-rust)]" aria-hidden="true" />
    case 'client': return <UserPlus className="h-4 w-4 text-[var(--color-success-foreground)]" aria-hidden="true" />
    case 'waitlist': return <Clock className="h-4 w-4 text-[var(--color-warning-foreground)]" aria-hidden="true" />
    case 'unread-message': return <MessageCircle className="h-4 w-4 text-foreground" aria-hidden="true" />
    case 'review-request': return <Star className="h-4 w-4 text-[var(--color-rust)]" aria-hidden="true" />
    case 'client-birthday': return <Gift className="h-4 w-4 text-[var(--color-rust)]" aria-hidden="true" />
    case 'guest-residency-ending': return <CalendarClock className="h-4 w-4 text-destructive" aria-hidden="true" />
  }
}

function typeBg(type: ExtendedInboxItemKind): string {
  switch (type) {
    case 'deposit':
    case 'waitlist':
      return 'bg-[var(--color-warning-bg)]'
    case 'client':
      return 'bg-[var(--color-success-bg)]'
    case 'form':
    case 'review-request':
    case 'client-birthday':
      return 'bg-[var(--color-chip-rust-bg)]'
    case 'unread-message':
      return 'bg-muted'
    case 'guest-residency-ending':
      return 'bg-destructive/10'
  }
}

function typeLabel(type: ExtendedInboxItemKind): string {
  switch (type) {
    case 'deposit': return 'Deposit'
    case 'form': return 'Form'
    case 'client': return 'Client'
    case 'waitlist': return 'Waitlist'
    case 'unread-message': return 'Message'
    case 'review-request': return 'Review'
    case 'client-birthday': return 'Birthday'
    case 'guest-residency-ending': return 'Residency'
  }
}

function ctaLabel(type: ExtendedInboxItemKind): string {
  switch (type) {
    case 'deposit': return 'Send reminder'
    case 'form': return 'Resend link'
    case 'client': return 'Send welcome'
    case 'waitlist': return 'Offer slot'
    case 'unread-message': return 'Reply'
    case 'review-request': return 'Send request'
    case 'client-birthday': return 'Send offer'
    case 'guest-residency-ending': return 'Market slots'
  }
}

function ctaIcon(type: ExtendedInboxItemKind) {
  switch (type) {
    case 'deposit': return <MessageSquare className="h-3.5 w-3.5" aria-hidden="true" />
    case 'form': return <Mail className="h-3.5 w-3.5" aria-hidden="true" />
    case 'client': return <Mail className="h-3.5 w-3.5" aria-hidden="true" />
    case 'waitlist': return <Zap className="h-3.5 w-3.5" aria-hidden="true" />
    case 'unread-message': return <MessageCircle className="h-3.5 w-3.5" aria-hidden="true" />
    case 'review-request': return <Star className="h-3.5 w-3.5" aria-hidden="true" />
    case 'client-birthday': return <Mail className="h-3.5 w-3.5" aria-hidden="true" />
    case 'guest-residency-ending': return <CalendarClock className="h-3.5 w-3.5" aria-hidden="true" />
  }
}

function initials(name: string): string {
  return name
    .split(' ')
    .map((p) => p[0] ?? '')
    .join('')
    .toUpperCase()
    .slice(0, 2)
}

function getScheduleLabel(item: RichInboxItem, type: ExtendedInboxItemKind): string | null {
  if (!item.scheduledAt) return null
  const scheduledAt = new Date(item.scheduledAt)
  if (!Number.isFinite(scheduledAt.getTime())) return null

  if (type === 'guest-residency-ending') {
    return `Ends ${format(scheduledAt, 'MMM d')}`
  }

  if (type === 'deposit' || type === 'form') {
    return `Session ${format(scheduledAt, 'MMM d, h:mm a')}`
  }

  return format(scheduledAt, 'MMM d, h:mm a')
}

function laterToday(): Date {
  const next = new Date()
  next.setHours(next.getHours() + 3, 0, 0, 0)
  return next
}

function tomorrowAtNine(): Date {
  const next = new Date()
  next.setDate(next.getDate() + 1)
  next.setHours(9, 0, 0, 0)
  return next
}

function nextMondayAtNine(): Date {
  const next = new Date()
  const day = next.getDay()
  const diff = day === 1 ? 7 : (8 - day) % 7
  next.setDate(next.getDate() + diff)
  next.setHours(9, 0, 0, 0)
  return next
}

export function InboxItemRow({
  item,
  urgency,
  isSelected,
  isFocused,
  members,
  currentUserId,
  onToggleSelect,
  onFocus,
  onRefresh,
}: InboxItemRowProps) {
  const [isPending, startTransition] = useTransition()
  const meta = URGENCY_META[urgency]
  const ts = new Date(item.timestamp)
  const isRecent = Date.now() - ts.getTime() < 24 * 60 * 60 * 1000

  // Extract the raw UUID from composite ids like "booking-<uuid>".
  const rawId = item.id.replace(/^(booking|consent|waitlist|client|review|birthday|residency|conv)-/, '')
  const kind = asExtended(item.type)
  const canChangeState = canUpdateAssignment(kind)
  const assignedMember = members.find((m) => m.userId === item.assignedTo) ?? null
  const scheduleLabel = getScheduleLabel(item, kind)
  const snoozedUntil = item.snoozedUntil ? new Date(item.snoozedUntil) : null
  const isSnoozed = snoozedUntil != null && Number.isFinite(snoozedUntil.getTime()) && snoozedUntil.getTime() > Date.now()
  const stateLabel = item.resolvedAt
    ? 'Resolved'
    : item.archivedAt
      ? 'Archived'
      : isSnoozed && snoozedUntil
        ? `Snoozed ${format(snoozedUntil, 'MMM d')}`
        : null

  function handleCta() {
    startTransition(async () => {
      let result: { ok: boolean; error?: string }

      if (kind === 'deposit') {
        result = await sendDepositReminderAction(rawId)
        if (result.ok) {
          toast.success('Deposit reminder sent')
          onRefresh()
        } else {
          toast.error(result.error ?? 'Failed to send reminder')
        }
        return
      }

      if (kind === 'form') {
        result = await resendFormLinkAction(rawId)
        if (result.ok) {
          toast.success('Form link resent')
          onRefresh()
        } else {
          toast.error(result.error ?? 'Failed to resend link')
        }
        return
      }

      if (kind === 'client') {
        result = await sendWelcomeAction(rawId)
        if (result.ok) {
          toast.success('Welcome email sent')
          onRefresh()
        } else {
          toast.error(result.error ?? 'Failed to send welcome email')
        }
        return
      }

      if (kind === 'review-request') {
        result = await sendReviewRequestAction(rawId)
        if (result.ok) {
          toast.success('Review request sent')
          onRefresh()
        } else {
          toast.error(result.error ?? "Couldn't send reminder. Try again or contact support.")
        }
        return
      }

      if (kind === 'client-birthday') {
        result = await sendBirthdayOfferAction(rawId)
        if (result.ok) {
          toast.success('Birthday offer sent')
          onRefresh()
        } else {
          toast.error(result.error ?? "Couldn't send reminder. Try again or contact support.")
        }
        return
      }

      if (kind === 'waitlist') {
        window.location.href = `/bookings/new?waitlist=${rawId}`
        return
      }

      if (kind === 'unread-message') {
        window.location.href = item.actionHref
        return
      }

      if (kind === 'guest-residency-ending') {
        window.location.href = item.actionHref
      }
    })
  }

  function handleResolve() {
    startTransition(async () => {
      const result = await resolveInboxItemAction(item.type, rawId)
      if (result.ok) {
        toast.success('Marked as resolved')
        onRefresh()
      } else {
        toast.error(result.error ?? 'Failed to resolve')
      }
    })
  }

  function handleArchive() {
    startTransition(async () => {
      const result = await archiveInboxItemAction(item.type, rawId)
      if (result.ok) {
        toast.success('Archived')
        onRefresh()
      } else {
        toast.error(result.error ?? 'Failed to archive')
      }
    })
  }

  function handleSnooze(until: Date) {
    startTransition(async () => {
      const result = await snoozeInboxItemAction(item.type, rawId, until)
      if (result.ok) {
        toast.success(`Snoozed until ${format(until, 'MMM d, h:mm a')}`)
        onRefresh()
      } else {
        toast.error(result.error ?? 'Failed to snooze')
      }
    })
  }

  async function handleAssign(userId: string | null) {
    const result = await assignInboxItemAction(item.type, rawId, userId)
    if (result.ok) {
      toast.success(userId ? 'Assigned' : 'Unassigned')
      onRefresh()
    } else {
      toast.error(result.error ?? 'Failed to assign')
    }
  }

  return (
    <div
      role="listitem"
      data-inbox-item-id={item.id}
      data-testid={`inbox-row-${item.type}-${item.id}`}
      data-selected={isSelected}
      onClick={() => onFocus(item.id)}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          onFocus(item.id)
        }
      }}
      tabIndex={0}
      className={cn(
        'group relative flex flex-col gap-3 bg-card px-4 py-3 transition-all',
        'before:absolute before:bottom-0 before:left-0 before:top-0 before:w-1 before:bg-transparent',
        'hover:bg-muted/25 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30',
        'sm:flex-row sm:items-center sm:gap-4',
        urgency === 'now' && 'before:bg-red-500',
        urgency === 'today' && 'before:bg-amber-500',
        urgency === 'this_week' && 'before:bg-rust',
        isFocused && 'bg-primary/5 ring-1 ring-inset ring-primary/20',
        isSelected && 'bg-primary/5',
        isPending && 'opacity-60',
      )}
    >
      <div className="flex min-w-0 flex-1 items-start gap-3">
        <Checkbox
          checked={isSelected}
          onCheckedChange={() => onToggleSelect(item.id)}
          onClick={(e) => e.stopPropagation()}
          aria-label={`Select ${item.title}`}
          className="mt-1 shrink-0"
        />

        <div className={cn('flex h-9 w-9 shrink-0 items-center justify-center rounded-lg', typeBg(kind))}>
          {typeIcon(kind)}
        </div>

        <div className="min-w-0 flex-1">
          <div className="flex min-w-0 flex-wrap items-center gap-2">
            <p className="min-w-0 truncate text-[13px] font-semibold leading-tight text-foreground">
              {item.title}
            </p>
            <span className="rounded-md border border-border/70 bg-background px-1.5 py-0.5 text-[10px] font-semibold text-muted-foreground">
              {typeLabel(kind)}
            </span>
            {stateLabel && (
              <span className="rounded-md border border-border/70 bg-muted px-1.5 py-0.5 text-[10px] font-semibold text-muted-foreground">
                {stateLabel}
              </span>
            )}
          </div>
          <p className="mt-0.5 truncate text-[12px] leading-snug text-muted-foreground">
            {item.subtitle}
          </p>
          <div className="mt-2 flex flex-wrap items-center gap-2 text-[11px] text-muted-foreground">
            <span className="inline-flex items-center gap-1 rounded-md bg-muted/70 px-1.5 py-0.5">
              <span
                className={cn('h-1.5 w-1.5 rounded-full', meta.dotClass)}
                aria-hidden="true"
              />
              {meta.label}
            </span>
            {scheduleLabel && (
              <span className="inline-flex items-center gap-1 rounded-md bg-muted/70 px-1.5 py-0.5">
                <CalendarClock className="h-3 w-3" aria-hidden="true" />
                {scheduleLabel}
              </span>
            )}
          </div>
        </div>
      </div>

      <div className="flex flex-wrap items-center justify-end gap-2 pl-12 sm:pl-0">
        {assignedMember && (
          <Avatar className="h-7 w-7 shrink-0 border border-border/70" aria-label={`Assigned to ${assignedMember.name}`}>
            <AvatarFallback className="bg-muted text-[9px]">
              {initials(assignedMember.name)}
            </AvatarFallback>
          </Avatar>
        )}

        <time
          dateTime={item.timestamp}
          className="hidden shrink-0 text-[11px] text-muted-foreground/70 md:block"
          title={format(ts, 'PPpp')}
        >
          {isRecent ? formatDistanceToNow(ts, { addSuffix: true }) : format(ts, 'MMM d')}
        </time>

        <Button
          variant="outline"
          size="sm"
          onClick={(e) => { e.stopPropagation(); handleCta() }}
          disabled={isPending}
          loading={isPending}
          className="h-8 shrink-0 gap-1.5 text-[11px]"
          aria-label={`${ctaLabel(kind)} for ${item.title}`}
        >
          {ctaIcon(kind)}
          <span className="hidden md:inline">{ctaLabel(kind)}</span>
        </Button>

        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                variant="ghost"
                size="sm"
                onClick={(e) => e.stopPropagation()}
                className="h-8 w-8 shrink-0 p-0 text-muted-foreground/70 opacity-100 hover:text-foreground sm:opacity-0 sm:group-hover:opacity-100 sm:group-focus-within:opacity-100"
                aria-label="More options"
              >
                <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
              </Button>
            }
          />
          <DropdownMenuContent align="end" side="bottom" className="min-w-44">
            <DropdownMenuItem
              onClick={(e) => { e.stopPropagation(); handleResolve() }}
              className="gap-2 text-xs"
            >
              <UserCheck className="h-3.5 w-3.5" aria-hidden="true" />
              Mark resolved
            </DropdownMenuItem>
            <DropdownMenuItem
              onClick={(e) => { e.stopPropagation(); handleArchive() }}
              className="gap-2 text-xs"
            >
              <Archive className="h-3.5 w-3.5" aria-hidden="true" />
              Archive
            </DropdownMenuItem>
            {canChangeState && (
              <DropdownMenuSub>
                <DropdownMenuSubTrigger className="gap-2 text-xs">
                  <TimerReset className="h-3.5 w-3.5" aria-hidden="true" />
                  Snooze
                </DropdownMenuSubTrigger>
                <DropdownMenuSubContent className="min-w-40">
                  <DropdownMenuItem
                    onClick={(e) => { e.stopPropagation(); handleSnooze(laterToday()) }}
                    className="gap-2 text-xs"
                  >
                    Later today
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    onClick={(e) => { e.stopPropagation(); handleSnooze(tomorrowAtNine()) }}
                    className="gap-2 text-xs"
                  >
                    Tomorrow 9 AM
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    onClick={(e) => { e.stopPropagation(); handleSnooze(nextMondayAtNine()) }}
                    className="gap-2 text-xs"
                  >
                    Next Monday
                  </DropdownMenuItem>
                </DropdownMenuSubContent>
              </DropdownMenuSub>
            )}
            <DropdownMenuSeparator />
            <DropdownMenuItem
              className="gap-2 text-xs"
              render={<Link href={item.actionHref} onClick={(e) => e.stopPropagation()} />}
            >
              <Eye className="h-3.5 w-3.5" aria-hidden="true" />
              View details
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>

        {canChangeState && (
          <div className="hidden sm:block" onClick={(e) => e.stopPropagation()}>
