}

'use client'

import { useState } from 'react'
import { ChevronDown, ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Urgency } from '@/lib/inbox/urgency'
import { URGENCY_META } from '@/lib/inbox/urgency'

interface UrgencyGroupProps {
  urgency: Urgency
  count: number
  defaultExpanded?: boolean
  children: React.ReactNode
}

export function UrgencyGroup({
  urgency,
  count,
  defaultExpanded = true,
  children,
}: UrgencyGroupProps) {
  const [expanded, setExpanded] = useState(defaultExpanded)
  const meta = URGENCY_META[urgency]
  const headerTone: Record<Urgency, string> = {
    now: 'bg-red-500/[0.04]',
    today: 'bg-amber-500/[0.05]',
    this_week: 'bg-[rgba(178,58,43,0.05)]',
    later: 'bg-muted/30',
  }

  return (
    <section
      aria-label={`${meta.label} (${count} items)`}
      data-testid={`urgency-group-${urgency}`}
      className={cn(
        'overflow-hidden rounded-lg border bg-card shadow-[var(--shadow-soft)]',
        meta.borderClass,
      )}
    >
      {/* Group header */}
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        aria-expanded={expanded}
        className={cn(
          'flex w-full items-center gap-3 px-4 py-3 text-left transition-colors hover:bg-muted/40',
          headerTone[urgency],
        )}
      >
        <span className="flex min-w-0 items-center gap-2">
          <span
            className={cn('h-2.5 w-2.5 shrink-0 rounded-full ring-4 ring-background', meta.dotClass)}
            aria-hidden="true"
          />
          <span className={cn('text-[11px] font-bold uppercase tracking-[0.12em]', meta.textClass)}>
            {meta.label}
          </span>
          <span className="rounded-full border border-border/70 bg-background px-2 py-0.5 text-[10px] font-semibold text-muted-foreground tabular-nums">
            {count}
          </span>
        </span>

        <span className="hidden min-w-0 truncate text-[12px] text-muted-foreground sm:inline">
          {urgency === 'now'
            ? 'Needs attention first'
            : urgency === 'today'
              ? 'Due soon'
              : urgency === 'this_week'
                ? 'Follow up this week'
                : 'Lower priority'}
        </span>

        {/* Expand/collapse chevron */}
        <span className="ml-auto text-muted-foreground/60" aria-hidden="true">
          {expanded
            ? <ChevronDown className="h-3.5 w-3.5" />
            : <ChevronRight className="h-3.5 w-3.5" />
          }
        </span>
      </button>

      {/* Items */}
      {expanded && (
        <div
          className="divide-y divide-border/50"
          role="list"
          aria-label={`${meta.label} items`}
        >
          {children}
        </div>
      )}
    </section>
  )
}

'use client'

import { useTransition } from 'react'
import { Archive, CheckCheck, X } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { AssignUserPicker } from './AssignUserPicker'
import type { TeamMember } from './AssignUserPicker'
import type { InboxItemType } from '@/components/inbox/InboxClient'
import {
  batchResolveAction,
  batchArchiveAction,
  batchAssignAction,
} from '@/app/(app)/inbox/actions'

interface SelectedItem {
  id: string
  type: InboxItemType
}

interface BatchActionBarProps {
  selected: SelectedItem[]
  members: TeamMember[]
  currentUserId: string
  onClear: () => void
  onRefresh: () => void
}

function toBatchItems(selected: SelectedItem[]) {
  return selected.map((s) => ({
    kind: s.type,
    id: s.id.replace(/^(booking|consent|waitlist|client)-/, ''),
  }))
}

export function BatchActionBar({
  selected,
  members,
  currentUserId,
  onClear,
  onRefresh,
}: BatchActionBarProps) {
  const [isPending, startTransition] = useTransition()
  const count = selected.length

  if (count === 0) return null

  function handleResolveAll() {
    startTransition(async () => {
      const result = await batchResolveAction(toBatchItems(selected))
      if (result.ok) {
        toast.success(`Resolved ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch resolve failed')
      }
    })
  }

  function handleArchiveAll() {
    startTransition(async () => {
      const result = await batchArchiveAction(toBatchItems(selected))
      if (result.ok) {
        toast.success(`Archived ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch archive failed')
      }
    })
  }

  async function handleAssignAll(userId: string | null) {
    const result = await batchAssignAction(toBatchItems(selected), userId)
    if (result.ok) {
      toast.success(
        userId
          ? `Assigned ${count} item${count > 1 ? 's' : ''}`
          : `Unassigned ${count} item${count > 1 ? 's' : ''}`,
      )
      onClear()
      onRefresh()
    } else {
      toast.error(result.error ?? 'Batch assign failed')
    }
  }

  return (
    <div
      role="toolbar"
      aria-label="Batch actions"
      aria-live="polite"
      className="sticky top-3 z-20 flex flex-col gap-3 rounded-lg border border-[var(--color-onyx)] bg-[var(--color-onyx)] px-4 py-3 text-sm text-[var(--color-bone)] shadow-[var(--shadow-lift)] sm:flex-row sm:items-center"
    >
      {/* Count + clear */}
      <span className="text-[13px] font-semibold">
        {count} selected
      </span>
      <button
        type="button"
        onClick={onClear}
        className="flex items-center gap-1 text-xs text-[rgba(247,247,245,0.62)] transition-colors hover:text-[var(--color-bone)]"
        aria-label="Clear selection"
      >
        <X className="h-3 w-3" aria-hidden="true" />
        Clear
      </button>

      <div className="flex flex-wrap items-center gap-2 sm:ml-auto">
        {/* Resolve all */}
        <Button
          size="sm"
          variant="outline"
          onClick={handleResolveAll}
          disabled={isPending}
          className="h-7 gap-1.5 border-[rgba(247,247,245,0.18)] bg-[rgba(247,247,245,0.08)] text-xs text-[var(--color-bone)] hover:bg-[rgba(247,247,245,0.14)] hover:text-[var(--color-bone)]"
        >
          <CheckCheck className="h-3.5 w-3.5" aria-hidden="true" />
          <span className="hidden sm:inline">Resolve all</span>
        </Button>

        {/* Archive all */}
        <Button
          size="sm"
          variant="outline"
          onClick={handleArchiveAll}
          disabled={isPending}
          className="h-7 gap-1.5 border-[rgba(247,247,245,0.18)] bg-[rgba(247,247,245,0.08)] text-xs text-[var(--color-bone)] hover:bg-[rgba(247,247,245,0.14)] hover:text-[var(--color-bone)]"
        >
          <Archive className="h-3.5 w-3.5" aria-hidden="true" />
          <span className="hidden sm:inline">Archive all</span>
        </Button>

        {/* Assign to... */}
        <AssignUserPicker
          members={members}
          currentUserId={currentUserId}
          currentAssignee={null}
          onAssign={handleAssignAll}
        />
      </div>
    </div>
  )
}

