-- Sprint A: Inbox v2 — extend item_kind constraint, add priority col, add missed_calls table

-- 1. Extend item_kind CHECK constraint to include the 4 new trigger types
ALTER TABLE inbox_assignments DROP CONSTRAINT IF EXISTS inbox_assignments_item_kind_check;
ALTER TABLE inbox_assignments ADD CONSTRAINT inbox_assignments_item_kind_check
  CHECK (item_kind IN (
    'deposit', 'form', 'client', 'waitlist',
    'booking-conflict', 'missed-call', 'low-inventory', 'failed-payment'
  ));

-- 2. Add priority column
ALTER TABLE inbox_assignments
  ADD COLUMN IF NOT EXISTS priority TEXT CHECK (priority IN ('high', 'med', 'low')) DEFAULT 'med';

-- 3. Create missed_calls table (lightweight log — Twilio doesn't surface missed calls natively)
CREATE TABLE IF NOT EXISTS missed_calls (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  studio_id     UUID NOT NULL REFERENCES studios(id) ON DELETE CASCADE,
  caller_number TEXT NOT NULL,
  called_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  replied_at    TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE missed_calls ENABLE ROW LEVEL SECURITY;

CREATE POLICY "studio members can manage missed_calls"
  ON missed_calls FOR ALL
  USING (
    studio_id IN (
      SELECT studio_id FROM studio_members
      WHERE user_id = auth.uid() AND deactivated_at IS NULL
    )
  );

CREATE INDEX IF NOT EXISTS missed_calls_studio_idx
  ON missed_calls (studio_id, called_at DESC);

CREATE INDEX IF NOT EXISTS missed_calls_unreplied_idx
  ON missed_calls (studio_id, replied_at)
  WHERE replied_at IS NULL;

-- Auto-update updated_at
CREATE TRIGGER missed_calls_updated_at
  BEFORE UPDATE ON missed_calls
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

