  // Non-DB kinds (unread-message, guest-residency-ending, review-request, client-birthday)
  // are not stored in inbox_assignments. Return ok silently.
  if (!isDBInboxKind(itemKind)) {
    return { ok: true }
  }

  const supabase = await createClient()

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(
      {
        studio_id: studioId,
        item_kind: itemKind,
        item_id: itemId,
        ...patch,
        updated_at: new Date().toISOString(),
      },
      { onConflict: 'studio_id,item_kind,item_id' },
    )

