import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { InboxClient } from '@/components/inbox/InboxClient'
import type { RichInboxItem, InboxItemType } from '@/components/inbox/InboxClient'
import type { TeamMember } from '@/components/inbox/AssignUserPicker'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import { formatCurrency } from '@/lib/utils'

export const metadata: Metadata = {
  title: 'Inbox — InkOS',
}

export default async function InboxPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { studioId, role, plan } = activeStudio
  const now = new Date()
  const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString()
  const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString()
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString()
  const sevenDaysFromNow = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString()

  // Fetch all data sources in parallel
  const [
    pendingBookingsRes,
    consentSubmissionsRes,
    waitlistRes,
    newClientsRes,
    assignmentsRes,
    membersRes,
    unreadConversationsRes,
    guestResidenciesRes,
    // Sprint B — 4 new trigger sources
    allUpcomingBookingsRes,
    missedCallsRes,
    inventoryItemsRes,
    failedPaymentsRes,
  ] = await Promise.all([
    // 1. Pending bookings — unpaid deposits
    supabase
      .from('bookings')
      .select('id, created_at, scheduled_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'pending')
      .eq('deposit_paid', false)
      .order('scheduled_at', { ascending: true })
      .limit(50),

    // 2. Consent required but not signed (last 7d)
    supabase
      .from('bookings')
      .select('id, client_id, created_at, scheduled_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('consent_required', true)
      .is('consent_signed_at', null)
      .gte('created_at', sevenDaysAgo)
      .order('scheduled_at', { ascending: true })
      .limit(30),

    // 3. Waitlist entries (last 24h)
    supabase
      .from('waitlist_entries')
      .select('id, client_id, created_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'active')
      .gte('created_at', oneDayAgo)
      .order('created_at', { ascending: false })
      .limit(20),

    // 4. New clients (last 7d)
    supabase
      .from('clients')
      .select('id, first_name, last_name, created_at')
      .eq('studio_id', studioId)
      .gte('created_at', sevenDaysAgo)
      .is('archived_at', null)
      .order('created_at', { ascending: false })
      .limit(10),

    // 5. Inbox assignments — state map
    supabase
      .from('inbox_assignments')
      .select('item_kind, item_id, assigned_to, snoozed_until, archived_at, resolved_at')
      .eq('studio_id', studioId)
      .limit(500),

    // 6. Studio members for assignment picker
    supabase
      .from('studio_members')
      .select('user_id, role, profiles(full_name, avatar_url)')
      .eq('studio_id', studioId)
      .is('deactivated_at', null),

    // 7. Unread message conversations
    supabase
      .from('conversations')
      .select('id, client_id, display_name, last_message_preview, last_message_at, unread_count, channel')
      .eq('studio_id', studioId)
      .is('archived_at', null)
      .gt('unread_count', 0)
      .order('last_message_at', { ascending: false })
      .limit(50),

    // 8. Guest residencies ending within 7 days
    supabase
      .from('studio_members')
      .select('id, user_id, role, ends_at, profiles(full_name)')
      .eq('studio_id', studioId)
      .eq('role', 'guest_artist')
      .not('ends_at', 'is', null)
      .gte('ends_at', now.toISOString())
      .lte('ends_at', sevenDaysFromNow)
      .is('deactivated_at', null)
      .order('ends_at', { ascending: true })
      .limit(20),

    // 9. All upcoming confirmed/pending bookings (for conflict detection)
    supabase
      .from('bookings')
      .select('id, artist_id, scheduled_at, end_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .in('status', ['confirmed', 'pending'])
      .gte('scheduled_at', now.toISOString())
      .order('scheduled_at', { ascending: true })
      .limit(200),

    // 10. Missed calls (unreplied, last 7 days)
    supabase
      .from('missed_calls')
      .select('id, caller_number, called_at')
      .eq('studio_id', studioId)
      .is('replied_at', null)
      .gte('called_at', sevenDaysAgo)
      .order('called_at', { ascending: false })
      .limit(20),

    // 11. Low inventory (all active items; filter client-side for column comparison)
    supabase
      .from('inventory_items')
      .select('id, name, category, current_stock, min_threshold')
      .eq('studio_id', studioId)
      .eq('is_active', true)
      .limit(200),

    // 12. Failed deposit payments (last 30 days)
    supabase
      .from('payments')
      .select('id, booking_id, client_id, amount_cents, failure_message, created_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'failed')
      .eq('type', 'deposit')
      .gte('created_at', thirtyDaysAgo)
      .order('created_at', { ascending: false })
      .limit(20),
  ])

  // Build assignment map: key = `${kind}-${item_id}`
  type AssignmentState = {
    assignedTo: string | null
    snoozedUntil: string | null
    archivedAt: string | null
    resolvedAt: string | null
  }

  const assignmentMap = new Map<string, AssignmentState>()
  for (const a of assignmentsRes.data ?? []) {
    assignmentMap.set(`${a.item_kind}-${a.item_id}`, {
      assignedTo: a.assigned_to,
      snoozedUntil: a.snoozed_until,
      archivedAt: a.archived_at,
      resolvedAt: a.resolved_at,
    })
  }

  function getAssignment(kind: InboxItemType, itemId: string): AssignmentState {
    return assignmentMap.get(`${kind}-${itemId}`) ?? {
      assignedTo: null,
      snoozedUntil: null,
      archivedAt: null,
      resolvedAt: null,
    }
  }

  // Normalize into RichInboxItem[]
  const items: RichInboxItem[] = []

  // Pending bookings (deposit overdue)
  for (const booking of pendingBookingsRes.data ?? []) {
    const clientRow = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('deposit', booking.id)

    items.push({
      id: `booking-${booking.id}`,
      type: 'deposit' as InboxItemType,
      title: 'Deposit pending',
      subtitle: clientName,
      actionLabel: 'View booking',
      actionHref: `/bookings/${booking.id}`,
      timestamp: booking.created_at,
      scheduledAt: booking.scheduled_at,
      ...a,
    })
  }

  // Bookings with unsigned consent forms
  for (const booking of consentSubmissionsRes.data ?? []) {
    const clientRow = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('form', booking.id)

    items.push({
      id: `consent-${booking.id}`,
      type: 'form' as InboxItemType,
      title: 'Consent form unsigned',
      subtitle: clientName,
      actionLabel: 'View booking',
      actionHref: `/bookings/${booking.id}`,
      timestamp: booking.created_at,
      scheduledAt: booking.scheduled_at,
      ...a,
    })
  }

  // Waitlist entries
  for (const entry of waitlistRes.data ?? []) {
    const clientRow = Array.isArray(entry.clients) ? entry.clients[0] : entry.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('waitlist', entry.id)

    items.push({
      id: `waitlist-${entry.id}`,
      type: 'waitlist' as InboxItemType,
      title: 'New waitlist signup',
      subtitle: clientName,
      actionLabel: 'View',
      actionHref: `/clients/${entry.client_id}`,
      timestamp: entry.created_at,
      scheduledAt: null,
      ...a,
    })
  }

  // New clients
  for (const client of newClientsRes.data ?? []) {
    const clientName = `${client.first_name}${client.last_name ? ` ${client.last_name}` : ''}`
    const a = getAssignment('client', client.id)

    items.push({
      id: `client-${client.id}`,
      type: 'client' as InboxItemType,
      title: 'New client',
      subtitle: clientName,
      actionLabel: 'View',
      actionHref: `/clients/${client.id}`,
      timestamp: client.created_at,
      scheduledAt: null,
      ...a,
    })
  }

  // Unread message conversations
  for (const conv of unreadConversationsRes.data ?? []) {
    const preview = conv.last_message_preview
      ? String(conv.last_message_preview).slice(0, 80)
      : 'New message'
    const clientId = conv.client_id as string | null
    const a = clientId ? getAssignment('client', clientId) : {
      assignedTo: null,
      snoozedUntil: null,
      archivedAt: null,
      resolvedAt: null,
    }

    items.push({
      id: `conv-${conv.id as string}`,
      type: 'unread-message' as InboxItemType,
      title: String(conv.display_name ?? 'Message'),
      subtitle: preview,
      actionLabel: 'Reply',
      actionHref: clientId ? `/clients/${clientId}?tab=comms` : '/inbox',
      timestamp: conv.last_message_at as string ?? new Date().toISOString(),
      scheduledAt: null,
      ...a,
    })
  }

  // Guest residencies ending within 7 days
  interface GuestResidencyRow {
    id: string
    user_id: string
    role: string
    ends_at: string
    profiles: { full_name: string | null } | { full_name: string | null }[] | null
  }

  for (const rawRow of (guestResidenciesRes.data ?? []) as unknown as GuestResidencyRow[]) {
    const profileRow = Array.isArray(rawRow.profiles) ? rawRow.profiles[0] : rawRow.profiles
    const artistName = profileRow?.full_name ?? 'Guest artist'

    const endsAt = new Date(rawRow.ends_at)
    const msUntil = endsAt.getTime() - now.getTime()
    const daysUntil = Math.ceil(msUntil / (24 * 60 * 60 * 1000))
    const formattedEndsAt = endsAt.toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
    })

    const a = getAssignment('guest-residency-ending' as InboxItemType, rawRow.id)
    const calendarHref = `/calendar?artist_id=${rawRow.user_id}&from=today&to=${rawRow.ends_at.slice(0, 10)}`

    items.push({
      id: `residency-${rawRow.id}`,
      type: 'guest-residency-ending' as InboxItemType,
      title: `${artistName} · Residency ending in ${daysUntil} day${daysUntil === 1 ? '' : 's'}`,
      subtitle: `Ends ${formattedEndsAt} · Market remaining slots`,
      actionLabel: 'Market slots',
      actionHref: calendarHref,
      timestamp: rawRow.ends_at,
      scheduledAt: rawRow.ends_at,
      ...a,
    })
  }

  // ── Sprint B: New triggers ─────────────────────────────────

  // 9. Booking conflicts — detect overlapping bookings per artist
  interface ConflictBookingRow {
    id: string
    artist_id: string
    scheduled_at: string
    end_at: string
    clients: { first_name: string; last_name: string | null } | { first_name: string; last_name: string | null }[] | null
  }

  const upcomingBookings = (allUpcomingBookingsRes.data ?? []) as unknown as ConflictBookingRow[]

  // Group by artist_id, find overlapping pairs
  const byArtist = new Map<string, ConflictBookingRow[]>()
  for (const b of upcomingBookings) {
    if (!byArtist.has(b.artist_id)) byArtist.set(b.artist_id, [])
    byArtist.get(b.artist_id)!.push(b)
  }

  const seenConflictPairs = new Set<string>()
  for (const [, artistBookings] of byArtist) {
    for (let i = 0; i < artistBookings.length; i++) {
      for (let j = i + 1; j < artistBookings.length; j++) {
        const a = artistBookings[i]!
        const b = artistBookings[j]!
        const aStart = new Date(a.scheduled_at).getTime()
        const aEnd = new Date(a.end_at).getTime()
        const bStart = new Date(b.scheduled_at).getTime()
        const bEnd = new Date(b.end_at).getTime()
        // Overlap: a starts before b ends AND b starts before a ends
        if (aStart < bEnd && bStart < aEnd) {
          const pairKey = [a.id, b.id].sort().join('-')
          if (seenConflictPairs.has(pairKey)) continue
          seenConflictPairs.add(pairKey)

          const aClient = Array.isArray(a.clients) ? a.clients[0] : a.clients
          const bClient = Array.isArray(b.clients) ? b.clients[0] : b.clients
          const aName = aClient ? `${aClient.first_name}${aClient.last_name ? ` ${aClient.last_name}` : ''}` : 'Client'
          const bName = bClient ? `${bClient.first_name}${bClient.last_name ? ` ${bClient.last_name}` : ''}` : 'Client'

          const conflictAt = new Date(a.scheduled_at)
          const conflictLabel = conflictAt.toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })

          const assignment = getAssignment('booking-conflict', pairKey)

          items.push({
            id: `conflict-${pairKey}`,
            type: 'booking-conflict' as InboxItemType,
            title: 'Booking conflict',
            subtitle: `${aName} + ${bName} · ${conflictLabel}`,
            actionLabel: 'Resolve',
            actionHref: `/calendar?date=${a.scheduled_at.slice(0, 10)}`,
            timestamp: a.scheduled_at,
            scheduledAt: a.scheduled_at,
            ...assignment,
          })
        }
      }
    }
  }

  // 10. Missed calls (unreplied)
  for (const call of missedCallsRes.data ?? []) {
    const a = getAssignment('missed-call', call.id)
    items.push({
      id: `missed-call-${call.id}`,
      type: 'missed-call' as InboxItemType,
      title: 'Missed call',
      subtitle: `${call.caller_number}`,
      actionLabel: 'Call back',
      actionHref: '/inbox',
      timestamp: call.called_at,
      scheduledAt: null,
      ...a,
    })
  }

  // 11. Low inventory (client-side column comparison)
  for (const item of inventoryItemsRes.data ?? []) {
    if (item.current_stock >= item.min_threshold) continue
    const a = getAssignment('low-inventory', item.id)
    items.push({
      id: `inventory-${item.id}`,
      type: 'low-inventory' as InboxItemType,
      title: `Low inventory · ${item.name}`,
      subtitle: `Stock: ${item.current_stock} units · Threshold: ${item.min_threshold}`,
      actionLabel: 'Reorder',
      actionHref: '/inventory',
      timestamp: new Date().toISOString(),
      scheduledAt: null,
      ...a,
    })
  }

  // 12. Failed deposit payments
  for (const payment of failedPaymentsRes.data ?? []) {
    const clientRow = Array.isArray(payment.clients) ? payment.clients[0] : payment.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('failed-payment', payment.id)

    items.push({
      id: `payment-${payment.id}`,
      type: 'failed-payment' as InboxItemType,
      title: `Failed payment · ${formatCurrency(payment.amount_cents)}`,
      subtitle: `${clientName}${payment.failure_message ? ` · ${payment.failure_message}` : ''}`,
      actionLabel: 'Retry payment',
      actionHref: `/payments`,
      timestamp: payment.created_at,
      scheduledAt: null,
      ...a,
    })
  }

  // Sort by timestamp descending
  items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())

  // Build team members list
  const members: TeamMember[] = (membersRes.data ?? []).map((m) => {
    const profileRow = Array.isArray(m.profiles) ? m.profiles[0] : m.profiles
    return {
      userId: m.user_id,
      name: profileRow?.full_name ?? m.user_id,
      role: m.role,
      avatarUrl: profileRow?.avatar_url ?? null,
    }
  })

  return (
    <InboxClient
      items={items}
      members={members}
      currentUserId={user.id}
      currentPlan={plan as PlanTier}
      currentRole={role as NavRole}
    />
  )
}

