    const endsAt = new Date(rawRow.ends_at)
    const msUntil = endsAt.getTime() - now.getTime()
    const daysUntil = Math.ceil(msUntil / (24 * 60 * 60 * 1000))
    const formattedEndsAt = endsAt.toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
    })

    const a = getAssignment('guest-residency-ending' as InboxItemType, rawRow.id)
    const calendarHref = `/calendar?artist_id=${rawRow.user_id}&from=today&to=${rawRow.ends_at.slice(0, 10)}`

    items.push({
      id: `residency-${rawRow.id}`,
      type: 'guest-residency-ending' as InboxItemType,
      title: `${artistName} · Residency ending in ${daysUntil} day${daysUntil === 1 ? '' : 's'}`,
      subtitle: `Ends ${formattedEndsAt} · Market remaining slots`,
      actionLabel: 'Market slots',
      actionHref: calendarHref,
      timestamp: rawRow.ends_at,
      scheduledAt: rawRow.ends_at,
      ...a,
    })
  }

  // ── Sprint B: New triggers ─────────────────────────────────

  // 9. Booking conflicts — detect overlapping bookings per artist
  interface ConflictBookingRow {
    id: string
    artist_id: string
    scheduled_at: string
    end_at: string
    clients: { first_name: string; last_name: string | null } | { first_name: string; last_name: string | null }[] | null
  }

  const upcomingBookings = (allUpcomingBookingsRes.data ?? []) as unknown as ConflictBookingRow[]

  // Group by artist_id, find overlapping pairs
  const byArtist = new Map<string, ConflictBookingRow[]>()
  for (const b of upcomingBookings) {
    if (!byArtist.has(b.artist_id)) byArtist.set(b.artist_id, [])
    byArtist.get(b.artist_id)!.push(b)
  }

  const seenConflictPairs = new Set<string>()
  for (const [, artistBookings] of byArtist) {
    for (let i = 0; i < artistBookings.length; i++) {
      for (let j = i + 1; j < artistBookings.length; j++) {
        const a = artistBookings[i]!
        const b = artistBookings[j]!
        const aStart = new Date(a.scheduled_at).getTime()
        const aEnd = new Date(a.end_at).getTime()
        const bStart = new Date(b.scheduled_at).getTime()
        const bEnd = new Date(b.end_at).getTime()
        // Overlap: a starts before b ends AND b starts before a ends
        if (aStart < bEnd && bStart < aEnd) {
          const pairKey = [a.id, b.id].sort().join('-')
          if (seenConflictPairs.has(pairKey)) continue
          seenConflictPairs.add(pairKey)

          const aClient = Array.isArray(a.clients) ? a.clients[0] : a.clients
          const bClient = Array.isArray(b.clients) ? b.clients[0] : b.clients
          const aName = aClient ? `${aClient.first_name}${aClient.last_name ? ` ${aClient.last_name}` : ''}` : 'Client'
          const bName = bClient ? `${bClient.first_name}${bClient.last_name ? ` ${bClient.last_name}` : ''}` : 'Client'

          const conflictAt = new Date(a.scheduled_at)
          const conflictLabel = conflictAt.toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })

          const assignment = getAssignment('booking-conflict', pairKey)

          items.push({
            id: `conflict-${pairKey}`,
            type: 'booking-conflict' as InboxItemType,
            title: 'Booking conflict',
            subtitle: `${aName} + ${bName} · ${conflictLabel}`,
            actionLabel: 'Resolve',
            actionHref: `/calendar?date=${a.scheduled_at.slice(0, 10)}`,
            timestamp: a.scheduled_at,
            scheduledAt: a.scheduled_at,
            ...assignment,
          })
        }
      }
    }
  }

  // 10. Missed calls (unreplied)
  for (const call of missedCallsRes.data ?? []) {
    const a = getAssignment('missed-call', call.id)
    items.push({
      id: `missed-call-${call.id}`,
      type: 'missed-call' as InboxItemType,
      title: 'Missed call',
      subtitle: `${call.caller_number}`,
      actionLabel: 'Call back',
      actionHref: '/inbox',
      timestamp: call.called_at,
      scheduledAt: null,
      ...a,
    })
  }

  // 11. Low inventory (client-side column comparison)
  for (const item of inventoryItemsRes.data ?? []) {
    if (item.current_stock >= item.min_threshold) continue
    const a = getAssignment('low-inventory', item.id)
    items.push({
      id: `inventory-${item.id}`,
      type: 'low-inventory' as InboxItemType,
      title: `Low inventory · ${item.name}`,
      subtitle: `Stock: ${item.current_stock} units · Threshold: ${item.min_threshold}`,
      actionLabel: 'Reorder',
      actionHref: '/inventory',
      timestamp: new Date().toISOString(),
      scheduledAt: null,
      ...a,
    })
  }

  // 12. Failed deposit payments
  for (const payment of failedPaymentsRes.data ?? []) {
    const clientRow = Array.isArray(payment.clients) ? payment.clients[0] : payment.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('failed-payment', payment.id)

    items.push({
      id: `payment-${payment.id}`,
      type: 'failed-payment' as InboxItemType,
      title: `Failed payment · ${formatCurrency(payment.amount_cents)}`,
      subtitle: `${clientName}${payment.failure_message ? ` · ${payment.failure_message}` : ''}`,
      actionLabel: 'Retry payment',
      actionHref: `/payments`,
      timestamp: payment.created_at,
      scheduledAt: null,
      ...a,
    })
  }

  // Sort by timestamp descending
  items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())

  // Build team members list
  const members: TeamMember[] = (membersRes.data ?? []).map((m) => {
    const profileRow = Array.isArray(m.profiles) ? m.profiles[0] : m.profiles
    return {
      userId: m.user_id,
      name: profileRow?.full_name ?? m.user_id,
      role: m.role,
      avatarUrl: profileRow?.avatar_url ?? null,
    }
  })

  return (
    <InboxClient
      items={items}
      members={members}
      currentUserId={user.id}
      currentPlan={plan as PlanTier}
      currentRole={role as NavRole}
    />
  )
}

