'use server'

import { revalidatePath } from 'next/cache'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio } from '@/lib/context/active-studio'
import { logger } from '@/lib/logger'
import { authedRatelimit } from '@/lib/rate-limit'
import type { InboxItemType } from '@/components/inbox/InboxClient'

// ─── Types ────────────────────────────────────────────────────

type ActionResult<T = undefined> =
  | { ok: true; data?: T; error?: never }
  | { ok: false; error: string; data?: never }

interface BatchItem {
  kind: InboxItemType
  id: string
}

/** Subset of InboxItemKind that inbox_assignments supports (excludes transient/extended kinds) */
type DBInboxItemKind = 'deposit' | 'form' | 'waitlist' | 'client'

function isDBInboxKind(kind: InboxItemType): kind is DBInboxItemKind {
  return kind === 'deposit' || kind === 'form' || kind === 'waitlist' || kind === 'client'
}

// ─── Rate-limit helper (W2) ───────────────────────────────────

/**
 * Returns the authenticated user's ID for use as a rate-limit key,
 * or null when the session is missing (caller should bail out early).
 */
async function getAuthUserId(): Promise<string | null> {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  return user?.id ?? null
}

async function checkSendRatelimit(
  userId: string,
  actionName: string,
): Promise<{ blocked: true; error: string } | { blocked: false }> {
  const { success } = await authedRatelimit.limit(`${userId}:${actionName}`)
  if (!success) {
    logger.warn({ userId, action: actionName }, 'inbox: rate limit exceeded')
    return { blocked: true, error: 'Too many requests. Please wait a minute before sending again.' }
  }
  return { blocked: false }
}

// ─── Helpers ──────────────────────────────────────────────────

async function upsertAssignment(
  studioId: string,
  itemKind: InboxItemType,
  itemId: string,
  patch: Record<string, string | null | boolean>,
): Promise<ActionResult> {
  // Non-DB kinds (unread-message, guest-residency-ending, review-request, client-birthday)
  // are not stored in inbox_assignments. Return ok silently.
  if (!isDBInboxKind(itemKind)) {
    return { ok: true }
  }

  const supabase = await createClient()

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(
      {
        studio_id: studioId,
        item_kind: itemKind,
        item_id: itemId,
        ...patch,
        updated_at: new Date().toISOString(),
      },
      { onConflict: 'studio_id,item_kind,item_id' },
    )

  if (error) {
    logger.error({ error: error.message, studioId, itemKind, itemId }, 'inbox: upsert failed')
    return { ok: false, error: error.message }
  }

  revalidatePath('/inbox')
  return { ok: true }
}

// ─── Individual actions ───────────────────────────────────────

export async function resolveInboxItemAction(
  itemKind: InboxItemType,
  itemId: string,
  note?: string,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()

  return upsertAssignment(studioId, itemKind, itemId, {
    resolved_at: new Date().toISOString(),
    ...(note ? { note } : {}),
  })
}

export async function archiveInboxItemAction(
  itemKind: InboxItemType,
  itemId: string,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()

  return upsertAssignment(studioId, itemKind, itemId, {
    archived_at: new Date().toISOString(),
  })
}

export async function assignInboxItemAction(
  itemKind: InboxItemType,
  itemId: string,
  assignedTo: string | null,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()

  return upsertAssignment(studioId, itemKind, itemId, {
    assigned_to: assignedTo,
  })
}

export async function snoozeInboxItemAction(
  itemKind: InboxItemType,
  itemId: string,
  until: Date,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()

  return upsertAssignment(studioId, itemKind, itemId, {
    snoozed_until: until.toISOString(),
  })
}

// ─── Batch actions ────────────────────────────────────────────

export async function batchResolveAction(items: BatchItem[]): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()
  const now = new Date().toISOString()

  const dbItems = items.filter((i) => isDBInboxKind(i.kind))
  if (dbItems.length === 0) { revalidatePath('/inbox'); return { ok: true } }

  const rows = dbItems.map((i) => ({
    studio_id: studioId,
    item_kind: i.kind as DBInboxItemKind,
    item_id: i.id,
    resolved_at: now,
    updated_at: now,
  }))

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(rows, { onConflict: 'studio_id,item_kind,item_id' })

  if (error) {
    logger.error({ error: error.message, count: items.length }, 'inbox: batch resolve failed')
    return { ok: false, error: error.message }
  }

  revalidatePath('/inbox')
  return { ok: true }
}

export async function batchArchiveAction(items: BatchItem[]): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()
  const now = new Date().toISOString()

  const dbItems = items.filter((i) => isDBInboxKind(i.kind))
  if (dbItems.length === 0) { revalidatePath('/inbox'); return { ok: true } }

  const rows = dbItems.map((i) => ({
    studio_id: studioId,
    item_kind: i.kind as DBInboxItemKind,
    item_id: i.id,
    archived_at: now,
    updated_at: now,
  }))

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(rows, { onConflict: 'studio_id,item_kind,item_id' })

  if (error) {
    logger.error({ error: error.message, count: items.length }, 'inbox: batch archive failed')
    return { ok: false, error: error.message }
  }

  revalidatePath('/inbox')
  return { ok: true }
}

export async function batchAssignAction(
  items: BatchItem[],
  assignedTo: string | null,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()
  const now = new Date().toISOString()

  const dbItems = items.filter((i) => isDBInboxKind(i.kind))
  if (dbItems.length === 0) { revalidatePath('/inbox'); return { ok: true } }

  const rows = dbItems.map((i) => ({
    studio_id: studioId,
    item_kind: i.kind as DBInboxItemKind,
    item_id: i.id,
    assigned_to: assignedTo,
    updated_at: now,
  }))

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(rows, { onConflict: 'studio_id,item_kind,item_id' })

  if (error) {
    logger.error({ error: error.message, count: items.length }, 'inbox: batch assign failed')
    return { ok: false, error: error.message }
  }

  revalidatePath('/inbox')
  return { ok: true }
}

// ─── One-click CTA actions ────────────────────────────────────

/**
 * Send a deposit reminder SMS to the client of the given booking.
 * Fetches booking → client phone → sends via Twilio → records resolved.
 */
export async function sendDepositReminderAction(
  bookingId: string,
): Promise<ActionResult> {
  const userId = await getAuthUserId()
  if (!userId) return { ok: false, error: 'Not authenticated' }
  const rl = await checkSendRatelimit(userId, 'sendDepositReminder')
  if (rl.blocked) return { ok: false, error: rl.error }

  const { studioId } = await getActiveStudio()
  const supabase = await createClient()

  // Fetch booking + client
  const { data: booking, error: bookingErr } = await supabase
    .from('bookings')
    .select('id, scheduled_at, clients!inner(first_name, phone)')
    .eq('id', bookingId)
    .eq('studio_id', studioId)
    .single()

  if (bookingErr || !booking) {
    return { ok: false, error: 'Booking not found' }
  }

  const client = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
  const phone = client?.phone

  if (!phone) {
    return { ok: false, error: 'Client has no phone number on file' }
  }

  // Send SMS
  try {
    const { sendSms } = await import('@/lib/sms/twilio')
    const firstName = client.first_name ?? 'there'
    const scheduledDate = new Date(booking.scheduled_at).toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
    })
    await sendSms({
      to: phone,
      body: `Hi ${firstName} — a reminder that your deposit is still outstanding for your appointment on ${scheduledDate}. Please pay to secure your slot. Reply STOP to opt out.`,
    })
  } catch (err) {
    if (err instanceof Error && err.constructor.name === 'TwilioNotConfiguredError') {
      logger.warn({ bookingId }, 'inbox: Twilio not configured — SMS skipped')
    } else {
      logger.error({ err, bookingId }, 'inbox: SMS send failed')
      return { ok: false, error: 'Failed to send SMS' }
    }
  }

  // Mark resolved
  const resolveResult = await upsertAssignment(studioId, 'deposit', bookingId, {
    resolved_at: new Date().toISOString(),
    note: 'Deposit reminder SMS sent',
  })

  return resolveResult
}

/**
 * Resend the consent form link for a booking that requires consent but hasn't signed.
 * bookingId here is the booking UUID (since form signals are now keyed on booking.id).
 */
export async function resendFormLinkAction(
  bookingId: string,
): Promise<ActionResult> {
  const userId = await getAuthUserId()
  if (!userId) return { ok: false, error: 'Not authenticated' }
  const rl = await checkSendRatelimit(userId, 'resendFormLink')
  if (rl.blocked) return { ok: false, error: rl.error }

  const { studioId } = await getActiveStudio()
  const supabase = await createClient()

  const { data: booking, error: bookingErr } = await supabase
    .from('bookings')
    .select('id, booking_token, clients!inner(first_name, email)')
    .eq('id', bookingId)
    .eq('studio_id', studioId)
    .single()

  if (bookingErr || !booking) {
    return { ok: false, error: 'Booking not found' }
  }

  const client = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
  const email = client?.email

  if (!email) {
    return { ok: false, error: 'Client has no email on file' }
  }

  try {
    const { sendEmail } = await import('@/lib/email/resend')
    const formUrl = `${process.env.NEXT_PUBLIC_APP_URL ?? ''}/consent/${booking.booking_token}`
    await sendEmail({
      to: email,
      template: 'booking_confirmation',
      data: {
        studioName: 'Your Studio',
        clientFirstName: client.first_name ?? 'there',
        serviceName: 'Your appointment',
        artistName: '',
        scheduledAt: new Date().toISOString(),
        endAt: new Date().toISOString(),
        durationMin: 0,
        priceCents: 0,
        depositCents: 0,
        depositPaid: false,
        bookingReference: booking.booking_token,
        depositPaymentUrl: formUrl,
      },
    })
  } catch (err) {
    logger.error({ err, bookingId }, 'inbox: form link resend failed')
    return { ok: false, error: 'Failed to send email' }
  }

  const resolveResult = await upsertAssignment(studioId, 'form', bookingId, {
    resolved_at: new Date().toISOString(),
    note: 'Consent form link resent via email',
  })

  return resolveResult
}

/**
 * Send a welcome email to a new client.
 */
export async function sendWelcomeAction(
  clientId: string,
): Promise<ActionResult> {
  const userId = await getAuthUserId()
  if (!userId) return { ok: false, error: 'Not authenticated' }
  const rl = await checkSendRatelimit(userId, 'sendWelcome')
  if (rl.blocked) return { ok: false, error: rl.error }

  const { studioId } = await getActiveStudio()
  const supabase = await createClient()

  const { data: client, error: clientErr } = await supabase
    .from('clients')
    .select('id, first_name, email')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (clientErr || !client) {
    return { ok: false, error: 'Client not found' }
  }

  if (!client.email) {
    return { ok: false, error: 'Client has no email on file' }
  }

  try {
    const { sendEmail } = await import('@/lib/email/resend')
    await sendEmail({
      to: client.email,
      template: 'booking_confirmation',
      data: {
        studioName: 'Your Studio',
        clientFirstName: client.first_name ?? 'there',
        serviceName: '',
        artistName: '',
        scheduledAt: new Date().toISOString(),
        endAt: new Date().toISOString(),
        durationMin: 0,
        priceCents: 0,
        depositCents: 0,
        depositPaid: false,
        bookingReference: '',
      },
    })
  } catch (err) {
    logger.error({ err, clientId }, 'inbox: welcome email failed')
    return { ok: false, error: 'Failed to send welcome email' }
  }

  const resolveResult = await upsertAssignment(studioId, 'client', clientId, {
    resolved_at: new Date().toISOString(),
    note: 'Welcome email sent',
  })

  return resolveResult
}

// ─── Review request & birthday — extended kinds not yet in InboxItemKind ─────
//
// These two kinds ('review-request', 'client-birthday') are not yet in the
// generated InboxItemKind union (pending Dato migration + pnpm db:types).
// We write directly to inbox_assignments with a string literal to avoid
// touching the generated types file. When db:types is regenerated with the
// new enum values, this comment and cast can be removed.

/**
 * Send a Google review request SMS to the client of a completed booking.
 * Falls back to email if no phone is on file.
 *
 * SMS: "Hey {first_name}! Hope you're loving your tattoo from {artist} at {studio}.
 *       If you have 60s, a review would mean the world: {review_link}"
 *
 * review_link = studios.google_review_url (TODO: add column via Dato migration).
 * Until then, falls back to the studio's public booking page (/book/{slug}).
 */
export async function sendReviewRequestAction(
  bookingId: string,
): Promise<ActionResult> {
  const userId = await getAuthUserId()
  if (!userId) return { ok: false, error: 'Not authenticated' }
  const rl = await checkSendRatelimit(userId, 'sendReviewRequest')
  if (rl.blocked) return { ok: false, error: rl.error }

  const { studioId, studio } = await getActiveStudio()
  const supabase = await createClient()

  const { data: booking, error: bookingErr } = await supabase
    .from('bookings')
    .select(`
      id,
      clients!inner(first_name, phone, email),
      artists!inner(display_name)
    `)
    .eq('id', bookingId)
    .eq('studio_id', studioId)
    .single()

  if (bookingErr || !booking) {
    return { ok: false, error: 'Booking not found or access denied' }
  }

  const client = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
  const artist = Array.isArray(booking.artists) ? booking.artists[0] : booking.artists

  if (!client) {
    return { ok: false, error: 'Client data missing' }
  }

  const firstName = client.first_name ?? 'there'
  const artistName = artist?.display_name ?? studio.name
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
  // TODO: use studios.google_review_url once Dato adds the column
  const reviewLink = `${appUrl}/book/${studio.slug}`

  const body =
    `Hey ${firstName}! Hope you're loving your tattoo from ${artistName} at ${studio.name}. ` +
    `If you have 60s, a review would mean the world: ${reviewLink}`

  const phone = client.phone
  let sent = false

  if (phone) {
    try {
      const { sendSms } = await import('@/lib/sms/twilio')
      await sendSms({ to: phone, body })
      sent = true
    } catch (err) {
      if (err instanceof Error && err.constructor.name === 'TwilioNotConfiguredError') {
        logger.warn({ bookingId }, 'inbox/review-request: Twilio not configured — falling back to email')
      } else {
        logger.error({ err, bookingId }, 'inbox/review-request: SMS failed — falling back to email')
      }
    }
  }

  if (!sent) {
    const email = client.email
    if (!email) {
      return { ok: false, error: 'Client has no phone or email on file' }
    }
    try {
      const { sendEmail } = await import('@/lib/email/resend')
      await sendEmail({
        to: email,
        template: 'booking_confirmation',
        data: {
          studioName: studio.name,
          clientFirstName: firstName,
          serviceName: 'your recent session',
          artistName,
          scheduledAt: new Date().toISOString(),
          endAt: new Date().toISOString(),
          durationMin: 0,
          priceCents: 0,
          depositCents: 0,
          depositPaid: true,
          bookingReference: bookingId,
          depositPaymentUrl: reviewLink,
        },
      })
    } catch (emailErr) {
      logger.error({ emailErr, bookingId }, 'inbox/review-request: email also failed')
      return { ok: false, error: "Couldn't send reminder. Try again or contact support." }
    }
  }

  // Stamp the sentinel so the Inbox query (WHERE review_request_sent_at IS NULL) hides this row.
  // Best-effort — never fail the action on stamp error.
  try {
    const { error: stampErr } = await supabase
      .from('bookings')
      .update({ review_request_sent_at: new Date().toISOString() })
      .eq('id', bookingId)
      .eq('studio_id', studioId)
    if (stampErr) logger.warn({ stampErr, bookingId }, 'inbox/review-request: failed to stamp sent_at — row may resurface')
  } catch (err) {
    logger.warn({ err, bookingId }, 'inbox/review-request: exception stamping sent_at')
  }

  revalidatePath('/inbox')
  return { ok: true }
}

/**
 * Send a birthday offer SMS (fallback email) to a client.
 *
 * Default: "Happy birthday {first_name}! 🎂 Treat yourself — we've got an opening
 *           this week. Book here: {booking_link}"
 *
 * Pass customMessage to override the body entirely.
 * booking_link = NEXT_PUBLIC_APP_URL + /book/{studio.slug}
 */
export async function sendBirthdayOfferAction(
  clientId: string,
  customMessage?: string,
): Promise<ActionResult> {
  const userId = await getAuthUserId()
  if (!userId) return { ok: false, error: 'Not authenticated' }
  const rl = await checkSendRatelimit(userId, 'sendBirthdayOffer')
  if (rl.blocked) return { ok: false, error: rl.error }

  const { studioId, studio } = await getActiveStudio()
  const supabase = await createClient()

  const { data: client, error: clientErr } = await supabase
    .from('clients')
    .select('id, first_name, phone, email')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (clientErr || !client) {
    return { ok: false, error: 'Client not found or access denied' }
  }

  const firstName = client.first_name ?? 'there'
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
  const bookingLink = `${appUrl}/book/${studio.slug}`

  const body =
    customMessage ??
    `Happy birthday ${firstName}! \uD83C\uDF82 Treat yourself \u2014 we\u2019ve got an opening this week. Book here: ${bookingLink}`

  const phone = client.phone
  let sent = false

  if (phone) {
    try {
      const { sendSms } = await import('@/lib/sms/twilio')
      await sendSms({ to: phone, body })
      sent = true
    } catch (err) {
      if (err instanceof Error && err.constructor.name === 'TwilioNotConfiguredError') {
        logger.warn({ clientId }, 'inbox/birthday: Twilio not configured — falling back to email')
      } else {
        logger.error({ err, clientId }, 'inbox/birthday: SMS failed — falling back to email')
      }
    }
  }

  if (!sent) {
    const email = client.email
    if (!email) {
      return { ok: false, error: 'Client has no phone or email on file' }
    }
    try {
      const { sendEmail } = await import('@/lib/email/resend')
      await sendEmail({
        to: email,
        template: 'booking_confirmation',
        data: {
          studioName: studio.name,
          clientFirstName: firstName,
          serviceName: 'Book your next session',
          artistName: studio.name,
          scheduledAt: new Date().toISOString(),
          endAt: new Date().toISOString(),
          durationMin: 0,
          priceCents: 0,
          depositCents: 0,
          depositPaid: true,
          bookingReference: clientId,
          depositPaymentUrl: bookingLink,
        },
      })
    } catch (emailErr) {
      logger.error({ emailErr, clientId }, 'inbox/birthday: email also failed')
      return { ok: false, error: "Couldn't send reminder. Try again or contact support." }
    }
  }

  // Stamp the sentinel so the Inbox query (WHERE birthday_offer_sent_at IS NULL) hides this row.
  // Best-effort — never fail the action on stamp error.
  try {
    const { error: stampErr } = await supabase
      .from('clients')
      .update({ birthday_offer_sent_at: new Date().toISOString() })
      .eq('id', clientId)
      .eq('studio_id', studioId)
    if (stampErr) logger.warn({ stampErr, clientId }, 'inbox/birthday: failed to stamp sent_at — row may resurface')
  } catch (err) {
    logger.warn({ err, clientId }, 'inbox/birthday: exception stamping sent_at')
  }

  revalidatePath('/inbox')
  return { ok: true }
}

/**
 * Returns pre-fill data for the booking drawer when offering a slot
 * to a waitlist entry. This action does not create a booking.
 */
export async function offerWaitlistSlotAction(
  waitlistEntryId: string,
): Promise<ActionResult<{ clientId: string; notes: string | null; serviceId: string | null; artistId: string | null }>> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()

  const { data: entry, error } = await supabase
    .from('waitlist_entries')
    .select('id, client_id, notes, service_id, artist_id')
    .eq('id', waitlistEntryId)
    .eq('studio_id', studioId)
    .single()

  if (error || !entry) {
    return { ok: false, error: 'Waitlist entry not found' }
  }

  return {
    ok: true,
    data: {
      clientId: entry.client_id,
      notes: entry.notes,
      serviceId: entry.service_id,
      artistId: entry.artist_id,
    },
  }
}

