/**
 * Retry a failed deposit payment via Dodo Payments.
 * Marks the payment record and resolves the inbox item.
 */
export async function retryPaymentAction(paymentId: string): Promise<ActionResult> {
  const userId = await getAuthUserId()
  if (!userId) return { ok: false, error: 'Not authenticated' }
  const rl = await checkSendRatelimit(userId, 'retryPayment')
  if (rl.blocked) return { ok: false, error: rl.error }

  const { studioId } = await getActiveStudio()
  const supabase = await createClient()

  const { data: payment, error: paymentErr } = await supabase
    .from('payments')
    .select('id, dodo_payment_id, amount_cents, status')
    .eq('id', paymentId)
    .eq('studio_id', studioId)
    .single()

  if (paymentErr || !payment) {
    return { ok: false, error: 'Payment not found' }
  }

  if (payment.status !== 'failed') {
    return { ok: false, error: 'Payment is not in a failed state' }
  }

  // Dodo Payments does not expose a retry endpoint — resolve inbox item so
  // the owner can manually re-collect via the booking page.
  logger.info({ paymentId, dodoId: payment.dodo_payment_id }, 'inbox: payment retry initiated — redirecting to payments page')

  return upsertAssignment(studioId, 'failed-payment', paymentId, {
    resolved_at: new Date().toISOString(),
    note: 'Payment retry initiated manually',
  })
}

/**
 * Batch snooze — snooze a set of inbox items until the given date.
 */
export async function batchSnoozeAction(
  items: BatchItem[],
  until: string,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()
  const now = new Date().toISOString()

  const dbItems = items.filter((i) => isDBInboxKind(i.kind))
  if (dbItems.length === 0) { revalidatePath('/inbox'); return { ok: true } }

  const rows = dbItems.map((i) => ({
    studio_id: studioId,
    item_kind: i.kind as DBInboxItemKind,
    item_id: i.id,
    snoozed_until: until,
    updated_at: now,
  }))

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(rows, { onConflict: 'studio_id,item_kind,item_id' })

  if (error) {
    logger.error({ error: error.message, count: items.length }, 'inbox: batch snooze failed')
    return { ok: false, error: error.message }
  }

  revalidatePath('/inbox')
  return { ok: true }
}

