function itemBelongsToTab(item: RichInboxItem, tab: TabKey): boolean {
  if (tab === 'all') return true
  if (tab === 'deposits') return item.type === 'deposit' || item.type === 'failed-payment'
  if (tab === 'forms') return item.type === 'form'
  if (tab === 'clients') return (
    item.type === 'client' || item.type === 'waitlist' ||
    item.type === 'client-birthday' || item.type === 'review-request'
  )
  if (tab === 'bookings') return item.type === 'booking-conflict' || item.type === 'guest-residency-ending'
  if (tab === 'inventory') return item.type === 'low-inventory'
  if (tab === 'inquiries') return item.type === 'unread-message' || item.type === 'missed-call'
  return true
}

