'use client'

import { useTransition } from 'react'
import { Archive, CheckCheck, TimerReset, X } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { AssignUserPicker } from './AssignUserPicker'
import type { TeamMember } from './AssignUserPicker'
import type { InboxItemType } from '@/components/inbox/InboxClient'
import {
  batchResolveAction,
  batchArchiveAction,
  batchAssignAction,
  batchSnoozeAction,
} from '@/app/(app)/inbox/actions'

interface SelectedItem {
  id: string
  type: InboxItemType
}

interface BatchActionBarProps {
  selected: SelectedItem[]
  members: TeamMember[]
  currentUserId: string
  onClear: () => void
  onRefresh: () => void
}

function toBatchItems(selected: SelectedItem[]) {
  return selected.map((s) => ({
    kind: s.type,
    id: s.id.replace(/^(booking|consent|waitlist|client|conflict|missed-call|inventory|payment|conv)-/, ''),
  }))
}

function tomorrowAtNine(): string {
  const next = new Date()
  next.setDate(next.getDate() + 1)
  next.setHours(9, 0, 0, 0)
  return next.toISOString()
}

function nextMondayAtNine(): string {
  const next = new Date()
  const day = next.getDay()
  const diff = day === 1 ? 7 : (8 - day) % 7
  next.setDate(next.getDate() + diff)
  next.setHours(9, 0, 0, 0)
  return next.toISOString()
}

const ghostBtn = 'h-7 gap-1.5 border-[rgba(247,247,245,0.18)] bg-[rgba(247,247,245,0.08)] text-xs text-[var(--color-bone)] hover:bg-[rgba(247,247,245,0.14)] hover:text-[var(--color-bone)]'

export function BatchActionBar({
  selected,
  members,
  currentUserId,
  onClear,
  onRefresh,
}: BatchActionBarProps) {
  const [isPending, startTransition] = useTransition()
  const count = selected.length

  if (count === 0) return null

  function handleResolveAll() {
    startTransition(async () => {
      const result = await batchResolveAction(toBatchItems(selected))
      if (result.ok) {
        toast.success(`Resolved ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch resolve failed')
      }
    })
  }

  function handleArchiveAll() {
    startTransition(async () => {
      const result = await batchArchiveAction(toBatchItems(selected))
      if (result.ok) {
        toast.success(`Archived ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch archive failed')
      }
    })
  }

  function handleSnoozeAll(until: string) {
    startTransition(async () => {
      const result = await batchSnoozeAction(toBatchItems(selected), until)
      if (result.ok) {
        toast.success(`Snoozed ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch snooze failed')
      }
    })
  }

  async function handleAssignAll(userId: string | null) {
    const result = await batchAssignAction(toBatchItems(selected), userId)
    if (result.ok) {
      toast.success(
        userId
          ? `Assigned ${count} item${count > 1 ? 's' : ''}`
          : `Unassigned ${count} item${count > 1 ? 's' : ''}`,
      )
      onClear()
      onRefresh()
    } else {
      toast.error(result.error ?? 'Batch assign failed')
    }
  }

  return (
    <div
      role="toolbar"
      aria-label="Batch actions"
      aria-live="polite"
      className="sticky top-3 z-20 flex flex-col gap-3 rounded-lg border border-[var(--color-onyx)] bg-[var(--color-onyx)] px-4 py-3 text-sm text-[var(--color-bone)] shadow-[var(--shadow-lift)] sm:flex-row sm:items-center"
    >
      <span className="text-[13px] font-semibold">{count} selected</span>
      <button
        type="button"
        onClick={onClear}
        className="flex items-center gap-1 text-xs text-[rgba(247,247,245,0.62)] transition-colors hover:text-[var(--color-bone)]"
        aria-label="Clear selection"
      >
        <X className="h-3 w-3" aria-hidden="true" />
        Clear
      </button>

      <div className="flex flex-wrap items-center gap-2 sm:ml-auto">
        <Button
          size="sm"
          variant="outline"
          onClick={handleResolveAll}
          disabled={isPending}
          className={ghostBtn}
        >
          <CheckCheck className="h-3.5 w-3.5" aria-hidden="true" />
          <span className="hidden sm:inline">Resolve all</span>
        </Button>

        <Button
          size="sm"
          variant="outline"
          onClick={handleArchiveAll}
          disabled={isPending}
          data-batch-archive-all
          className={ghostBtn}
        >
          <Archive className="h-3.5 w-3.5" aria-hidden="true" />
          <span className="hidden sm:inline">Archive all</span>
        </Button>

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button size="sm" variant="outline" disabled={isPending} className={ghostBtn}>
              <TimerReset className="h-3.5 w-3.5" aria-hidden="true" />
              <span className="hidden sm:inline">Snooze</span>
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="min-w-36">
            <DropdownMenuItem onClick={() => handleSnoozeAll(tomorrowAtNine())} className="text-xs">
              Tomorrow 9 AM
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => handleSnoozeAll(nextMondayAtNine())} className="text-xs">
              Next Monday
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>

        <AssignUserPicker
          members={members}
          currentUserId={currentUserId}
          currentAssignee={null}
          onAssign={handleAssignAll}
        />
      </div>
    </div>
  )
}

