  const { studioId, studio, role, plan, allMemberships } = activeStudio

  // S15: resolve active location (depends on studioId — sequential, not Promise.all)
  const activeLocation = await getActiveLocation(studioId, role)

  // Fetch user profile + dynamic badge counts in parallel
  const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
  const nowIso = new Date().toISOString()
  const twentyFourHoursFromNow = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
  const todayStart = new Date()
  todayStart.setHours(0, 0, 0, 0)
  const todayEnd = new Date()
  todayEnd.setHours(23, 59, 59, 999)

  // S22: resolve artist record id for artist-role MTD filter
  // artists.profile_id links to profiles.id (= user.id)
  let artistIdForMtd: string | undefined
  if (role === 'artist') {
    const { data: artistRow } = await supabase
      .from('artists')
      .select('id')
      .eq('profile_id', user.id)
      .eq('studio_id', studioId)
      .maybeSingle()
    artistIdForMtd = artistRow?.id
  }

  const [
    profileResult,
    inboxPendingRes,
    inboxConsentRes,
    inboxWaitlistRes,
    calendarTodayRes,
    clientsTotalRes,
    inventoryLowRes,
    inboxUnreadConvsRes,
  ] = await Promise.all([
    supabase
      .from('profiles')
      .select('full_name, avatar_url')
      .eq('id', user.id)
      .single(),
    // Inbox OVERDUE: deposits unpaid with session in next 24h
    supabase
      .from('bookings')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .eq('deposit_paid', false)
      .in('status', ['pending', 'confirmed'])
      .gte('scheduled_at', nowIso)
      .lte('scheduled_at', twentyFourHoursFromNow),
    // Inbox OVERDUE: consent unsigned with session in next 24h
    supabase
      .from('bookings')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .eq('consent_required', true)
      .is('consent_signed_at', null)
      .gte('scheduled_at', nowIso)
      .lte('scheduled_at', twentyFourHoursFromNow),
    // (kept for existing variable slot — counts waitlist as before)
    supabase
      .from('waitlist_entries')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .gte('created_at', oneDayAgo),
    // Calendar: bookings scheduled today
    supabase
      .from('bookings')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .gte('scheduled_at', todayStart.toISOString())
      .lte('scheduled_at', todayEnd.toISOString()),
    // Clients: total for studio
    supabase
      .from('clients')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId),
    // Inventory: items at zero stock (proxy for low-stock alert)
    supabase
      .from('inventory_items')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .eq('is_active', true)
      .eq('current_stock', 0),

    // Inbox: unread conversation count
    supabase
      .from('conversations')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .is('archived_at', null)
      .gt('unread_count', 0),
  ])

  // S22: Pins + MTD commissions + dynamic breadcrumb labels — parallel after main badge fetches
  const canViewCommissions = role === 'owner' || role === 'admin' || role === 'artist'
  const currentPathname = (await headers()).get('x-pathname') ?? '/dashboard'
  const [pinnedItems, mtdResult, dynamicLabels] = await Promise.all([
    fetchUserPins(user.id, studioId),
    canViewCommissions
      ? getMtdCommissionTotal(supabase, studioId, artistIdForMtd ? { artistId: artistIdForMtd } : undefined)
      : Promise.resolve(null),
    resolveDynamicLabels(supabase, currentPathname),
  ])
  const mtdCommissionCents = mtdResult?.totalCents ?? null

  // Permissions
  const permissionsSet =
    studioId && user ? await getUserPermissions(studioId, user.id) : new Set<string>()
  const permissionKeys = [...permissionsSet]

  // Sidebar state from cookie
  const cookieStore = await cookies()
  const sidebarOpen = cookieStore.get('sidebar_state')?.value !== 'false'

  const profile = profileResult.data
  const userName = profile?.full_name ?? user.email?.split('@')[0] ?? 'You'
  const userEmail = user.email ?? ''
  const userAvatarUrl = profile?.avatar_url ?? null
  const studioName = studio.name
  const studioLogoUrl = studio.logo_url ?? null
  const studioSlug = studio.slug

  // Compute dynamic badge counts (OVERDUE-only for inbox — shows critical items needing immediate action)
  const inboxCount =
    (inboxPendingRes.count ?? 0) +
    (inboxConsentRes.count ?? 0)

  const dynamicBadges: DynamicBadgeCounts = {
    inbox: inboxCount,
    calendar: calendarTodayRes.count ?? 0,
    clients: clientsTotalRes.count ?? 0,
    inventory: inventoryLowRes.count ?? 0,
  }

  return (
    <PermissionsProvider permissionKeys={permissionKeys}>
      {/* S15: StudioParamSync handles ?studio=X deep links — renders null */}
      <StudioParamSync currentStudioId={studioId} />
      <SidebarProvider defaultOpen={sidebarOpen} className="h-svh">
        <AppSidebar
          locationCount={activeLocation.allLocations.length}
          plan={plan}
          studioName={studioName}
          studioLogoUrl={studioLogoUrl}
          studioSlug={studioSlug}
          role={role}
          permissionKeys={permissionKeys}
          dynamicBadges={dynamicBadges}
          allMemberships={allMemberships}
          currentStudioId={studioId}
          pinnedItems={pinnedItems}
        />
        <AppHeader
          studioName={studioName}
          studioSlug={studioSlug}
          userName={userName}
          userEmail={userEmail}
          userAvatarUrl={userAvatarUrl}
          role={role}
          plan={plan}
          allMemberships={allMemberships}
          currentStudioId={studioId}
          currentLocationId={activeLocation.locationId}
          allLocations={activeLocation.allLocations}
          permissionKeys={permissionKeys}
          dynamicBadges={dynamicBadges}
          mtdCommissionCents={mtdCommissionCents}
          canViewCommissions={canViewCommissions}
          dynamicLabels={dynamicLabels}
        >
          {children}
        </AppHeader>
      </SidebarProvider>
    </PermissionsProvider>
  )
}

'use client'

import { useTransition } from 'react'
import { Archive, CheckCheck, TimerReset, X } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { AssignUserPicker } from './AssignUserPicker'
import type { TeamMember } from './AssignUserPicker'
import type { InboxItemType } from '@/components/inbox/InboxClient'
import {
  batchResolveAction,
  batchArchiveAction,
  batchAssignAction,
  batchSnoozeAction,
} from '@/app/(app)/inbox/actions'

interface SelectedItem {
  id: string
  type: InboxItemType
}

interface BatchActionBarProps {
  selected: SelectedItem[]
  members: TeamMember[]
  currentUserId: string
  onClear: () => void
  onRefresh: () => void
}

function toBatchItems(selected: SelectedItem[]) {
  return selected.map((s) => ({
    kind: s.type,
    id: s.id.replace(/^(booking|consent|waitlist|client|conflict|missed-call|inventory|payment|conv)-/, ''),
  }))
}

function tomorrowAtNine(): string {
  const next = new Date()
  next.setDate(next.getDate() + 1)
  next.setHours(9, 0, 0, 0)
  return next.toISOString()
}

function nextMondayAtNine(): string {
  const next = new Date()
  const day = next.getDay()
  const diff = day === 1 ? 7 : (8 - day) % 7
  next.setDate(next.getDate() + diff)
  next.setHours(9, 0, 0, 0)
  return next.toISOString()
}

const ghostBtn = 'h-7 gap-1.5 border-[rgba(247,247,245,0.18)] bg-[rgba(247,247,245,0.08)] text-xs text-[var(--color-bone)] hover:bg-[rgba(247,247,245,0.14)] hover:text-[var(--color-bone)]'

export function BatchActionBar({
  selected,
  members,
  currentUserId,
  onClear,
  onRefresh,
}: BatchActionBarProps) {
  const [isPending, startTransition] = useTransition()
  const count = selected.length

  if (count === 0) return null

  function handleResolveAll() {
    startTransition(async () => {
      const result = await batchResolveAction(toBatchItems(selected))
      if (result.ok) {
        toast.success(`Resolved ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch resolve failed')
      }
    })
  }

  function handleArchiveAll() {
    startTransition(async () => {
      const result = await batchArchiveAction(toBatchItems(selected))
      if (result.ok) {
        toast.success(`Archived ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch archive failed')
      }
    })
  }

  function handleSnoozeAll(until: string) {
    startTransition(async () => {
      const result = await batchSnoozeAction(toBatchItems(selected), until)
      if (result.ok) {
        toast.success(`Snoozed ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch snooze failed')
      }
    })
  }

  async function handleAssignAll(userId: string | null) {
    const result = await batchAssignAction(toBatchItems(selected), userId)
    if (result.ok) {
      toast.success(
        userId
          ? `Assigned ${count} item${count > 1 ? 's' : ''}`
          : `Unassigned ${count} item${count > 1 ? 's' : ''}`,
      )
      onClear()
      onRefresh()
    } else {
      toast.error(result.error ?? 'Batch assign failed')
    }
  }

  return (
    <div
      role="toolbar"
      aria-label="Batch actions"
      aria-live="polite"
      className="sticky top-3 z-20 flex flex-col gap-3 rounded-lg border border-[var(--color-onyx)] bg-[var(--color-onyx)] px-4 py-3 text-sm text-[var(--color-bone)] shadow-[var(--shadow-lift)] sm:flex-row sm:items-center"
    >
      <span className="text-[13px] font-semibold">{count} selected</span>
      <button
        type="button"
        onClick={onClear}
        className="flex items-center gap-1 text-xs text-[rgba(247,247,245,0.62)] transition-colors hover:text-[var(--color-bone)]"
        aria-label="Clear selection"
      >
        <X className="h-3 w-3" aria-hidden="true" />
        Clear
      </button>

      <div className="flex flex-wrap items-center gap-2 sm:ml-auto">
        <Button
          size="sm"
          variant="outline"
          onClick={handleResolveAll}
          disabled={isPending}
          className={ghostBtn}
        >
          <CheckCheck className="h-3.5 w-3.5" aria-hidden="true" />
          <span className="hidden sm:inline">Resolve all</span>
        </Button>

        <Button
          size="sm"
          variant="outline"
          onClick={handleArchiveAll}
          disabled={isPending}
          data-batch-archive-all
          className={ghostBtn}
        >
          <Archive className="h-3.5 w-3.5" aria-hidden="true" />
          <span className="hidden sm:inline">Archive all</span>
        </Button>

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button size="sm" variant="outline" disabled={isPending} className={ghostBtn}>
              <TimerReset className="h-3.5 w-3.5" aria-hidden="true" />
              <span className="hidden sm:inline">Snooze</span>
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="min-w-36">
            <DropdownMenuItem onClick={() => handleSnoozeAll(tomorrowAtNine())} className="text-xs">
              Tomorrow 9 AM
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => handleSnoozeAll(nextMondayAtNine())} className="text-xs">
              Next Monday
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>

        <AssignUserPicker
          members={members}
          currentUserId={currentUserId}
          currentAssignee={null}
          onAssign={handleAssignAll}
        />
      </div>
    </div>
  )
}

